const ANTONYMS = {"version":"antonym-candidates-20261126","corpusVersion":"v10-boundary-r2-20261126","source":{"name":"ChineseAntiword 公开反义词表","repository":"https://github.com/liuhuanyong/ChineseAntiword","commit":"9bdec2c2c3761d4ab0ac53227f6d8460a11dc0ca","file":"antisem.txt","sha256":"f2a8cf89617e6f2fa04c676c544c09582868fb4868941dca340c528052d886d5","description":"作者说明为网络资源采集，未提供逐词辞书出处。"},"counts":{"exactMatchedPairs":2653,"displayCandidatePairs":100,"displayWords":188,"awaitingReviewPairs":2553,"researcherConfirmedPairs":0},"records":[{"id":"ANT:1c8a0c303e249377","words":["减少","增加"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3505,"first":"减少","second":"增加"},{"line":8111,"first":"增加","second":"减少"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"①化学反应速率：在一定条件下，单位时间内某化学反应的反应物浓度的减少或生成物浓度的增加，用来衡量化学反应进行的快慢程度。","path":"04_化学精讲精练/第十一章 化学反应速率与化学平衡.txt","line":"3","textbook":"04_化学精讲精练","lesson":"第十一章 化学反应速率与化学平衡"},{"sentence":"化学反应速率是用来衡量化学反应进行的快慢的，用单位时间里反应物浓度的减少或生成物浓度的增加来表示，常用的单位是摩尔每升每秒或摩尔每升每分。参加化学反应的物质的性质是决定化学反应速率的主要因素，不同的物质参加的化学反应，具有不同的反应速率。此外，温度、浓度、压强和催化剂等也能影响化学反应速率。","path":"03_化学专业汉语科技汉语系列_clean_v3/10_化学反应速率和化学平衡.txt","line":"53","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"10_化学反应速率和化学平衡"},{"sentence":"化学反应速率是用来衡量化学反应进行的快慢程度的。反应速率是指在一定条件下单位时间内某化学反应的反应物转变为生成物的速率。对于均匀体系的恒容反应，习惯用单位时间内反应物浓度的减少或生成物浓度的增加来表示，而且习惯取正值。浓度单位通常用摩尔每升，时间单位视反应快慢，可分别用秒、分或小时等表示。这样，化学反应速率的单位可为摩尔每升每秒、摩尔每升每分、摩尔每升每小时等。","path":"03_化学专业汉语科技汉语系列_clean_v3/10_化学反应速率和化学平衡.txt","line":"9","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"10_化学反应速率和化学平衡"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3a2a7970a98295ba","words":["升高","降低"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3485,"first":"降低","second":"升高"},{"line":5791,"first":"升高","second":"降低"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"氯化钠的溶解度受温度的影响很小，随着温度升高溶解度仅略微增加。硫酸锂的溶解度随温度的升高而减小。一般情况下气体在水中的溶解度随着温度升高而降低。","path":"03_化学专业汉语科技汉语系列_clean_v3/05_溶液.txt","line":"20","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"05_溶液"},{"sentence":"在二氧化硫中，硫的氧化数处于中间状态，为正四，既可以升高到正六，又可以降低到零和负二，所以二氧化硫既有氧化性又有还原性。","path":"03_化学专业汉语科技汉语系列_clean_v3/08_氧族元素.txt","line":"39","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"08_氧族元素"},{"sentence":"氧族元素是元素周期表中的第VIA族元素，包括氧、硫、硒、碲、钋五种元素。氧族元素最外层都有六个电子，在化学反应中可以得到两个电子，生成氧化数负二的化合物；它们原子的最外电子层的六个电子或其中的四个电子也可以发生偏移，生成氧化数为正六或正四的化合物。随着核电荷数的增加，氧族元素单质的熔点、沸点逐渐升高，非金属性逐渐减弱，氧化性降低。","path":"03_化学专业汉语科技汉语系列_clean_v3/08_氧族元素.txt","line":"3","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"08_氧族元素"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0dd322927240fc1e","words":["上升","下降"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6950,"first":"下降","second":"上升"},{"line":11850,"first":"上升","second":"下降"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"把小球用细线悬挂起来，把小球拉到一定高度A点，然后放开，小球就摆动起来。小球在摆动中，动能与势能相互转化。我们看到，小球可以摆动到跟A点高度相同的B点。小球在A、B点没有速度，随着小球的下降，速度逐渐增大，在最低点，小球的速度达到最大值。之后，随着小球向B点摆动，小球上升，速度逐渐减小。我们看到，物体运动过程中，随动能增大，物体的势能减小；反之，随动能减小，物体的势能增大。","path":"06_物理专业汉语科技汉语系列_clean_v3/05_机械能_第四节_机械能守恒定律.txt","line":"4","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"05_机械能_第四节_机械能守恒定律"},{"sentence":"由正弦曲线可以看出：当 sz增大到sz时，曲线是上升的；当 x 由sz增大到 sz 时，曲线是下降的。又因为正弦函数是周期函数，所以","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"179","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"},{"sentence":"由余弦曲线可以看出：当 sz增大到 sz 时，曲线是上升的；当 x 由 sz 增大到 π 时，曲线是下降的。又因为余弦函数是周期函数，所以","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"213","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"}],"evidenceUnit":"original_source_line"},{"id":"ANT:df73b1cb98de36be","words":["提高","降低"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3485,"first":"降低","second":"提高"},{"line":6198,"first":"提高","second":"降低"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"疫苗产生作用的普遍机制是，消灭活性或减少毒性的病原体进入人体后，人体免疫系统能够区别出相关病原体的特征，并对如何抵抗它产生记忆，如果再遇到这个病原体，就能有效地产生免疫反应，使人体不再受到传染病带来的伤害。由疫苗导致的免疫反应与自然感染病原体而产生的免疫反应类似，但是风险不同。如果自然感染病毒或细菌等病原体，生病康复后身体里也可能会产生抗体并获得免疫力，但会付出很高的代价，例如孕妇感染风疹会导致宝宝出生时有缺陷，普通人感染某些病原体还有可能死亡。而疫苗中使用的病原体往往是消灭活性或减少毒性的，人的免疫系统通常能够有效应对，所以引起疾病的风险较低。现在还有通过基因技术等开发的新型疫苗，在很大程度上提高了效果并降低了风险。","path":"02_理工中文/13_第十三章公共卫生危机处理_01_疫苗是战疫的“武器”.txt","line":"4","textbook":"02_理工中文","lesson":"13_第十三章公共卫生危机处理_01_疫苗是战疫的“武器”"},{"sentence":"移动支付随时、随地的特点给人们的生活带来很多便捷。人们的衣食住行一部智能手机就能实时完成，在家就可以进行水电缴费、购物和打车，实现多方面的互联。在很多领域，移动支付都产生了深刻的影响。最显著的是移动支付促进了居民的消费，使生活更加便利快捷；在促进消费的同时，它还可以提高财产安全性，降低现金丢失的可能性。","path":"02_理工中文/07_第七章移动支付_01_ 移动支付.txt","line":"9","textbook":"02_理工中文","lesson":"07_第七章移动支付_01_ 移动支付"},{"sentence":"此外，功率半导体还为节能降碳带来了新的发展空间。功率半导体能够创造新的电能生产和应用方式，比如电动汽车等，从而减少化石能源的使用；功率半导体的使用可以提高能源利用效率，比如变频节能、直流输电，从而降低能源损耗。","path":"02_理工中文/12_第十二章神秘半导体_03_功率半导体助力碳中和.txt","line":"9","textbook":"02_理工中文","lesson":"12_第十二章神秘半导体_03_功率半导体助力碳中和"}],"evidenceUnit":"original_source_line"},{"id":"ANT:32c27793ad5b8555","words":["减弱","增强"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3506,"first":"减弱","second":"增强"},{"line":8109,"first":"增强","second":"减弱"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"⑤元素的性质与元素在周期表中位置的关系：同一周期元素从左至右，原子半径减小，金属性减弱，非金属性增强。同一主族元素从上到下：原子半径增大，金属性增强，非金属性减弱。铯是金属性最强的元素；氟是非金属性最强的元素。","path":"04_化学精讲精练/第三章  基本概念与基本理论.txt","line":"47","textbook":"04_化学精讲精练","lesson":"第三章  基本概念与基本理论"},{"sentence":"在同一周期中，从左到右，各元素核电荷数依次增多，原子半径逐渐减小，失电子能力减弱，得电子能力增强，因此，元素的金属性逐渐减弱，非金属性逐渐增强。","path":"03_化学专业汉语科技汉语系列_clean_v3/03_基本概念和基本理论.txt","line":"136","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"03_基本概念和基本理论"},{"sentence":"氮族元素是周期表中的第VA族元素，包括氮、磷、砷、锑、铋五种元素。在周期表中从上到下，随着原子半径逐渐增大，元素非金属性逐渐减弱，金属性逐渐增强。其中，氮和磷是典型的非金属，砷是准金属，锑和铋是金属。","path":"03_化学专业汉语科技汉语系列_clean_v3/09_氮族元素.txt","line":"3","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"09_氮族元素"}],"evidenceUnit":"original_source_line"},{"id":"ANT:30a74281b559f1d4","words":["减速","加速"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3624,"first":"加速","second":"减速"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"牛顿总结了前人的经验，指出了加速和减速的原因，并指出了这个原因与运动的关系，这就是牛顿第一定律：","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第一节_牛顿第一定律.txt","line":"11","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第一节_牛顿第一定律"},{"sentence":"伽利略所设计的实验是这样的：实验装置跟现在的一样，实验时若没有摩擦力，小球在这个理想实验中会怎样运动。把小球放到左边斜面的某一个高度，放手后，做加速运动，所以小球从斜面上滚下时，会越滚越快；到右边斜面下端时，开始做减速运动，小球会越滚越慢。在没有摩擦力的情况下，小球应达到左边的释放高度。改变右边斜面的倾角，使之变小，小球仍要达到同样的高度，就要在斜面上走更远的距离。当右边倾角为零时，小球将一直滚下去也永远达不到左边的释放高度，因此这个速度将保持不变。这个实验虽然是个理想实验，但却是符合科学道理的。法国科学家笛卡尔补充和完善了伽利略的论点，提出了惯性定律：如果没有其他原因，运动的物体将继续以同一速度沿着一条直线运动，既不会停下来，也不会偏离原来的方向。伽利略和笛卡尔对物体的运动做了准确的描述，但是没有指明加速、减速和匀速运动的原因是什么，以及这个原因与运动的关系是什么。而牛顿回答了这个问题。","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第一节_牛顿第一定律.txt","line":"8","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第一节_牛顿第一定律"},{"sentence":"在桌上放着一本物理书，它是静止的，怎样才能让它运动起来呢？要用力去推它。从这个例子可以看出物体要运动，需要对它施加力的作用。力是使物体运动的原因吗？这是一个运动和力的关系问题。这个问题在sz多年前人们就对它进行了研究。sz多年前，古希腊哲学家亚里士多德根据当时人们对运动和力的关系的认识提出一个观点：必须有力作用在物体上，物体才能运动。这种观点的提出是很自然的。我们从周围的事情出发，很容易就会得到这个结论，如车不推就不走，门不拉不开等。到sz世纪，意大利科学家伽利略指出这种说法是错误的，他分析道：运动的车停下来是由于摩擦力的原因，运动物体减速的原因是摩擦力。伽利略提出了自己的看法，他指出：物体一旦具有某一速度，没有加速和减速的原因，这个速度将保持不变。这里所指的减速的原因就是摩擦力。","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第一节_牛顿第一定律.txt","line":"6","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第一节_牛顿第一定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:c57085b58a635e5d","words":["减慢","加快"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3508,"first":"减慢","second":"加快"},{"line":3628,"first":"加快","second":"减慢"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"飞机能飞上天除了靠发动机的动力以外，飞机的机翼是必不可少的。你是否注意过机翼的形状，这种形状对于飞机上天有什么作用呢？飞机机翼的上表面是个向上的弧形，机翼下表面是平的。飞机起飞前，要在跑道上快跑一段很长的距离，飞机向前快速前进，空气相对飞机向后运动。空气流到机翼前缘，就会分成上下两股气流，分别沿机翼上下表面流过，然后在机翼后缘重新汇合向后流去。机翼上表面比较凸出，流管较细，因此流速加快，压力降低；机翼下表面的气流受到阻挡，流管变粗，流速减慢，压力增大，于是上下表面出现了压力差。机翼下方的压力比上方大，这样便产生了升力，从而托起飞机，使飞机克服自身重力，飞上蓝天。","path":"15_基础科技汉语教程阅读课本下/31_01_飞机为什么能飞上天？.txt","line":"3","textbook":"15_基础科技汉语教程阅读课本下","lesson":"31_01_飞机为什么能飞上天？"}],"evidenceUnit":"original_source_line"},{"id":"ANT:14f16d1b6ec47dca","words":["伸长","缩短"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5365,"first":"缩短","second":"伸长"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"把sz的图像上的所有的点纵坐标不变，横坐标缩短sz）或伸长sz）到原来的sz倍，得到sz；","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"317","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"},{"sentence":"sz. 把所得的 sz 图像各点的纵坐标不变，横坐标缩短sz）或伸长sz）到原来的sz倍，得到 sz；","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"312","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"},{"sentence":"sz. 把所得的 sz 的图像各点横坐标不变，纵坐标伸长sz）或缩短sz）到原来的 A 倍，就得到 sz。","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"313","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0893bdf4c98a4b5b","words":["延长","缩短"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5365,"first":"缩短","second":"延长"},{"line":7445,"first":"延长","second":"缩短"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"科学家对有关数据进行分析后发现，在过去的sz年里，天文台所在地的平均气温明显升高，气候确有变暖趋势。同时，气温变化与太阳活动周期表现出显著的相关性：当太阳处在一个较长活动周期内时，气温较低；活动周期短时，气温较高。太阳活动周期一般为sz年，有时会延长或缩短几年。","path":"30_中级汉语分类阅读科技篇II/14_气象_全球变暖：21世纪最危险的挑战.txt","line":"15","textbook":"30_中级汉语分类阅读科技篇II","lesson":"14_气象_全球变暖：21世纪最危险的挑战"}],"evidenceUnit":"original_source_line"},{"id":"ANT:aa757d06ceb44ef7","words":["扩大","缩小"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":13156,"first":"缩小","second":"扩大"},{"line":14029,"first":"扩大","second":"缩小"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"由上式可以看出，如果扩大到原来的几倍，那么就缩小到原来的几分之一；反过来，如果缩小到原来的几分之一，那么就扩大到原来的几倍。我们把两个量之间的这种关系叫做反比例关系。","path":"15_基础科技汉语教程阅读课本下/57_02_反比例函数.txt","line":"5","textbook":"15_基础科技汉语教程阅读课本下","lesson":"57_02_反比例函数"},{"sentence":"在算式sz中，如果x扩大到原来的几倍，y就会缩小到原来的几分之一；反之，如果x缩小到原来的几分之一，y就扩大到原来的几倍。我们把两个量之间的这种关系叫做反比例关系。","path":"22_科技汉语听说教程/13_变换解释.txt","line":"52","textbook":"22_科技汉语听说教程","lesson":"13_变换解释"},{"sentence":"矩形的面积是sz平方厘米，这时长y和宽x之间的关系是sz。由此可以看出，如果x扩大到原来的几倍，那么y就缩小到原来的几分之一；反过来，如果x缩小到原来的几分之一，那么y就扩大到原来的几倍。我们把两个量之间的这种关系叫做反比例关系。","path":"27_新编科技汉语中级阅读教程/13_函数.txt","line":"5","textbook":"27_新编科技汉语中级阅读教程","lesson":"13_函数"}],"evidenceUnit":"original_source_line"},{"id":"ANT:ef6ecdbd43f79bdd","words":["放大","缩小"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2236,"first":"放大","second":"缩小"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"首先，我们来了解一些分形的科普小知识。关于分形，首先涉及的是其自相似性，所谓自相似性是指局部是整体成比例缩小的性质。通俗一点说，就是当用不同倍数的照相机拍照，无论放大倍数如何改变，看到的照片都是相似的。由此，你能想象科赫雪花曲线的自相似性吗？","path":"02_理工中文/01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密.txt","line":"3","textbook":"02_理工中文","lesson":"01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密"},{"sentence":"物镜把远处的景物会聚成倒立的、缩小的实像，就等于把远处的景物移到了成像的地方。而这个倒立像又恰好落在目镜的前焦点处。目镜相当于一个放大镜，对着目镜看过去，可以看到一个放大了许多倍的虚像。这样，即使很远的景物，在望远镜里看来也就仿佛近在眼前，看得特别清楚。","path":"13_基础科技汉语教程听说课本下/38_望远镜·电子显微镜.txt","line":"5","textbook":"13_基础科技汉语教程听说课本下","lesson":"38_望远镜·电子显微镜"},{"sentence":"单击“最大化”按钮，窗口将放大到它的最大尺寸，此时最大化按钮变成还原按钮；单击“还原”按钮，窗口会还原到原来的大小；单击“最小化”按钮，窗口将缩小为任务栏上的一个按钮。","path":"26_科技汉语中级教程/14_第十四单元 Windows XP 操作系统_第三节 Windows XP的基本操作.txt","line":"27","textbook":"26_科技汉语中级教程","lesson":"14_第十四单元 Windows XP 操作系统_第三节 Windows XP的基本操作"}],"evidenceUnit":"original_source_line"},{"id":"ANT:bacdd64783f55afb","words":["递减","递增"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1806,"first":"递增","second":"递减"},{"line":1809,"first":"递减","second":"递增"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"如果当x增大时，y也随之增大，则称函数为增函数（或递增函数）；如果当x增大时，y随之减小，则称函数为减函数（或递减函数）。具有这种性质的函数称为具有单调性。","path":"26_科技汉语中级教程/03_第三单元 函数_第三节 函数的单调性.txt","line":"38","textbook":"26_科技汉语中级教程","lesson":"03_第三单元 函数_第三节 函数的单调性"},{"sentence":"在初等函数里，一次函数sz当sz时递增，当sz时递减；幂函数sz当是整数时，其不是奇函数就是偶函数；sz和ln x都是递增的；三角函数都是周期函数，而且不是奇函数就是偶函数。","path":"18_科技汉语基础篇/02_函数及其图像_03_相关阅读.txt","line":"26","textbook":"18_科技汉语基础篇","lesson":"02_函数及其图像_03_相关阅读"},{"sentence":"元素周期表中共有sz种元素，每一种元素都有一个编号，大小恰好等于该元素原子的核内质子数目，这个编号称为原子序数。在元素周期表中，元素是以元素的原子序数排列，最小的排行最先。表中一横行称为一个周期，一列称为一个族。同一周期内，从左到右，元素核外电子层数相同，最外层电子数依次递增，原子半径递减，金属性逐渐减弱，非金属性逐渐增强。同一族中，由上而下，最外层电子数相同，核外电子层数逐渐增多，原子序数递增，金属性递增，非金属性递减。元素周期表的意义重大，科学家正是据此来寻找新型元素及化合物的。","path":"23_科技汉语简明教程/03_元素周期律和元素周期表_科技基础.txt","line":"58","textbook":"23_科技汉语简明教程","lesson":"03_元素周期律和元素周期表_科技基础"}],"evidenceUnit":"original_source_line"},{"id":"ANT:bc2709f6732b2ff9","words":["收缩","膨胀"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4821,"first":"膨胀","second":"收缩"},{"line":5641,"first":"收缩","second":"膨胀"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"水银和酒精具有热胀冷缩的特点，随着温度的升高或降低，水银和酒精的体积会明显地膨胀或收缩，在温度计中看到的就是水银柱或酒精柱的高度上升或下降。在温度计上刻上适当的刻度，人们就可以读出相应的温度。由于水银和酒精能够用来测量温度，因此被称为测温物质。","path":"16_基础科技汉语教程听力课本/21_水银温度计和酒精温度计.txt","line":"4","textbook":"16_基础科技汉语教程听力课本","lesson":"21_水银温度计和酒精温度计"},{"sentence":"飞机上装有两种测量高度的仪表。一种仪表叫做气压式高度表，它是利用大气压强随高度变化的规律制成的。在地球表面上，海平面的大气压强最高，随着高度的增加，大气压强就按着一定的规律逐渐减小，因此只要测出压强，就可以推算出高度。气压式高度表中有一个用薄膜做的膜盒，它会随着外界压力的变化而发生膨胀或收缩，带动指针转动，直接显示出飞机的高度。","path":"13_基础科技汉语教程听说课本下/31_飞机怕小鸟·飞机飞行的高度.txt","line":"8","textbook":"13_基础科技汉语教程听说课本下","lesson":"31_飞机怕小鸟·飞机飞行的高度"},{"sentence":"体温表是用来测量身体温度的。体温表的水银泡比较大，泡里水银的微小膨胀，就能使管内水银面的位置发生显著的变化。这样能使体温表的测量能够精确到十分之一度。体温表在A点附近内径非常细，下边泡里的水银膨胀时可以通过这里上升到上面去。体温表离开身体后，水银变冷收缩，就在这里断开，使上面的水银回不到泡里去。因此，体温表离开身体以后，还能表示身体的温度。","path":"12_基础科技汉语教程听说课本上/21_温度计.txt","line":"7","textbook":"12_基础科技汉语教程听说课本上","lesson":"21_温度计"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8d0533e6d57ec144","words":["冷却","加热"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3626,"first":"加热","second":"冷却"},{"line":4163,"first":"冷却","second":"加热"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"暖气放在屋子外墙的窗户下面是科学的。因为冬天冷空气大部分是从窗户进来的，冷空气进来就碰上了暖气散发出来的热气，把冷空气变成了热空气。热空气上升并沿着屋顶流向屋子各处，散发出刚才得到的热。热空气冷却后下降，流回暖气处，暖气又把冷空气加热，热空气再上升。这样，冷、热空气形成了对流，使整个屋子都暖和了。","path":"16_基础科技汉语教程听力课本/12_暖气的科学.txt","line":"3","textbook":"16_基础科技汉语教程听力课本","lesson":"12_暖气的科学"},{"sentence":"热塑性和热固性：聚乙烯等高分子受热后软化，温度足够高时会流动，这样的物品加热后可加工成另一种形状。这种受热易变形，冷却时固化成型，且能如此反复进行的受热行为就是高分子的热塑性。高分子的热固性是指受热不能流动，形状不易改变的性质。其实质是高分子化合物受热进一步聚合而固化，不再回复到原来状态。","path":"03_化学专业汉语科技汉语系列_clean_v3/18_合成材料.txt","line":"23","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"18_合成材料"},{"sentence":"散热、冷却器件实时状态下实施系统自适应当前状态的控制。根据电池包状态，系统进行自适应状态的控制，当电池包温度大于等于一定温度时，系统自动开启散热功能进行冷却，当温度小于等于一定温度时，散热系统关闭，保证了高温情况下的散热良好，让电池包在最优的条件下工作。控制状态下自动识别和自动切换电池包处于低温状态时也会自动识别，当小于等于一定温度时，电池包识别后自动开启加热功能，当加热温度达到一定温度后，停止加热，自动切换为充电模式，系统控制电池包在不同温度下切换为最优模式进行工作。","path":"19_科技汉语/06_纯电动车用动力电池热管理系统设计.txt","line":"8","textbook":"19_科技汉语","lesson":"06_纯电动车用动力电池热管理系统设计"}],"evidenceUnit":"original_source_line"},{"id":"ANT:9fce5dfe3304e179","words":["凝结","蒸发"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4573,"first":"凝结","second":"蒸发"},{"line":8011,"first":"蒸发","second":"凝结"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"水在平常温度下，吸收周围的热量，慢慢地变为水蒸气飞散到空气中，这种现象叫做蒸发。地上的水变成了水蒸气，蒸发到天上，就形成了白云。如果水蒸气凝结成较大的水滴，水滴就会落下来形成雨。","path":"12_基础科技汉语教程听说课本上/03_水蒸气.txt","line":"4","textbook":"12_基础科技汉语教程听说课本上","lesson":"03_水蒸气"}],"evidenceUnit":"original_source_line"},{"id":"ANT:6e3a55dc9324a583","words":["运动","静止"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3232,"first":"静止","second":"运动"},{"line":7056,"first":"运动","second":"静止"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"通常做直线运动的物体，一般要经历从静止到运动，又由运动到静止的过程，在这一过程中，物体运动的快慢是不断变化的。例如，飞机起飞的时候，在跑道上越来越快；火车进站的时候，运动越来越慢。它们的共同特点是在相等的时间内位移不相等，我们称之为变速直线运动。","path":"06_物理专业汉语科技汉语系列_clean_v3/02_运动_第三节_ 变速直线运动.txt","line":"3","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"02_运动_第三节_ 变速直线运动"},{"sentence":"自由落体运动是物体只在重力的作用下从静止开始下落的运动，是一种初速度为零的匀加速直线运动。","path":"06_物理专业汉语科技汉语系列_clean_v3/02_运动_第四节_ 自由落体运动.txt","line":"11","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"02_运动_第四节_ 自由落体运动"},{"sentence":"自由落体运动：物体只在重力的作用下从静止开始下落的运动。自由落体运动是初速度为零的匀加速直线运动。","path":"06_物理专业汉语科技汉语系列_clean_v3/02_运动_第四节_ 自由落体运动.txt","line":"3","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"02_运动_第四节_ 自由落体运动"}],"evidenceUnit":"original_source_line"},{"id":"ANT:cbfca450b55ffc0b","words":["流动","静止"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3992,"first":"流动","second":"静止"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"我们知道，地球周围的大气是有压力的。一个物体在静止的时候，各个方向受到的大气压力是一样的。但是，当它运动起来以后，也就是造成空气在表面的流动时，各处受到的压力就不一样了，气流速度快的地方压力小，速度慢的地方压力大。飞机就是利用大气压力差产生的升力飞上天的。","path":"15_基础科技汉语教程阅读课本下/31_01_飞机为什么能飞上天？.txt","line":"2","textbook":"15_基础科技汉语教程阅读课本下","lesson":"31_01_飞机为什么能飞上天？"}],"evidenceUnit":"original_source_line"},{"id":"ANT:70a98a0c89a07e3c","words":["吸引","排斥"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4869,"first":"排斥","second":"吸引"},{"line":7000,"first":"吸引","second":"排斥"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"同名磁极互相排斥，异名磁极互相吸引。","path":"06_物理专业汉语科技汉语系列_clean_v3/08_磁场_第一节_磁场 安培定律.txt","line":"36","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"08_磁场_第一节_磁场 安培定律"},{"sentence":"自然界只存在两种电荷：正电荷和负电荷。同种电荷相互排斥，异种电荷相互吸引。","path":"06_物理专业汉语科技汉语系列_clean_v3/06_电场_第一节_电荷与库伦定律.txt","line":"36","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"06_电场_第一节_电荷与库伦定律"},{"sentence":"自然界只存在两种电荷：正电荷和负电荷，而且同种电荷相互排斥，异种电荷相互吸引。","path":"06_物理专业汉语科技汉语系列_clean_v3/06_电场_第一节_电荷与库伦定律.txt","line":"5","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"06_电场_第一节_电荷与库伦定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:611f139aca71eaf2","words":["引力","斥力"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1408,"first":"斥力","second":"引力"},{"line":7271,"first":"引力","second":"斥力"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"其中，r代表两个带电体之间的距离；q1代表第一个带电体的电荷量；q2代表第二个带电体的电荷量；k是比例系数，叫作静电力常量。当两个点电荷所带电荷为同种时，它们之间的作用力为斥力；反之，当两个点电荷所带电荷为异种时，它们之间的作用力为引力。","path":"18_科技汉语基础篇/06_电学的几个基本概念_02_知识链接.txt","line":"9","textbook":"18_科技汉语基础篇","lesson":"06_电学的几个基本概念_02_知识链接"}],"evidenceUnit":"original_source_line"},{"id":"ANT:2ca516b9de88438b","words":["正极","负极"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2101,"first":"负极","second":"正极"},{"line":7949,"first":"正极","second":"负极"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在潮湿的空气里，钢铁表面吸附了一层薄薄的水膜，这层水膜里含有少量氢离子和氢氧根离子，还溶解了氧气，结果在钢铁表面形成了一层电解质溶液，它跟钢铁里的铁和少量的碳恰好形成无数微小的原电池。在这些原电池里，铁是负极，碳是正极。铁失去电子而被氧化：","path":"03_化学专业汉语科技汉语系列_clean_v3/13_原电池和电解池.txt","line":"18","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"13_原电池和电解池"},{"sentence":"电极：正、负极有电极材料决定：相对活泼的金属为负极，较不活泼的金属为正极。","path":"03_化学专业汉语科技汉语系列_clean_v3/13_原电池和电解池.txt","line":"49","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"13_原电池和电解池"},{"sentence":"这种能够把化学能转化为电能的装置叫做原电池。在原电池中，电子流出的一极是负极，电极被氧化。电子流入的一极是正极，氢离子在正极上被还原。","path":"03_化学专业汉语科技汉语系列_clean_v3/13_原电池和电解池.txt","line":"10","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"13_原电池和电解池"}],"evidenceUnit":"original_source_line"},{"id":"ANT:957fa8f67c340c7a","words":["充电","放电"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1405,"first":"充电","second":"放电"},{"line":2233,"first":"放电","second":"充电"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"电容器是储存电荷的装置。在两个正对的平行金属板中间夹上一层绝缘物质，就形成一个最简单的电容器，叫做平行板电容器。这两块金属板叫做电容器的极板。电容器的工作包括充电和放电两个过程。充电时，电源的能量转化为电场能储存在电容器中；放电时，电场能又转化为其他形式的能量。","path":"26_科技汉语中级教程/08_第八单元 电路基础_第三节 电场与电容器.txt","line":"19","textbook":"26_科技汉语中级教程","lesson":"08_第八单元 电路基础_第三节 电场与电容器"},{"sentence":"如图所示，把充电后的电容器的两个极板相连接，两个极板上的电荷互相中和，电容器就不再带电，这个过程就叫放电。放电后，两个极板间就不存在电场，电场能就转化成其他形式的能。","path":"06_物理专业汉语科技汉语系列_clean_v3/06_电场_第五节_电容.txt","line":"4","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"06_电场_第五节_电容"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8b46a5b8a15a2eb9","words":["输入","输出"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5577,"first":"输入","second":"输出"},{"line":5578,"first":"输出","second":"输入"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"输入设备、输出设备和外存储器合称为计算机的外部设备。","path":"13_基础科技汉语教程听说课本下/35_电子计算机的组成.txt","line":"11","textbook":"13_基础科技汉语教程听说课本下","lesson":"35_电子计算机的组成"},{"sentence":"电子计算机种类虽然很多，但是一般来说，它们都由以下五个部分组成：运算器、控制器、存储器、输入设备和输出设备。","path":"13_基础科技汉语教程听说课本下/35_电子计算机的组成.txt","line":"2","textbook":"13_基础科技汉语教程听说课本下","lesson":"35_电子计算机的组成"},{"sentence":"计算机在处理汉字时，汉字的输入、存储、处理和输出过程中所使用的汉字编码不同，分别对应输入码、机内码和字形码。它们之间可以相互转换。","path":"02_理工中文/06_第六章汉字编码与输入法_03_汉字字符编码.txt","line":"7","textbook":"02_理工中文","lesson":"06_第六章汉字编码与输入法_03_汉字字符编码"}],"evidenceUnit":"original_source_line"},{"id":"ANT:682a757ecb1dccfa","words":["分解","合成"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2163,"first":"分解","second":"合成"},{"line":3094,"first":"合成","second":"分解"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"力的分解是力的合成的逆过程，在实际中，我们不仅仅需要求力的合成，有时，我们需要把一个力分解成几个力，这几个力的作用效果与原来的那个力的作用效果相同，这几个力就叫作分力，求一个力的分力就叫力的分解。","path":"06_物理专业汉语科技汉语系列_clean_v3/01_力_第三节_力的合成与分解.txt","line":"9","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"01_力_第三节_力的合成与分解"},{"sentence":"含有多种颜色的光被分解为单色光的现象叫做光的色散。太阳光通过棱镜后，发生了色散，被分解成各种颜色的光，如果用一个白屏来承接，在白屏上就形成一条彩色的光带，颜色依次是红、橙、黄、绿、蓝、靛、紫，这个光带叫做光谱。如果让其中一种色彩的光再经过棱镜，它不能再发生色散，这种色光叫做单色光。由几种单色光合成的光叫做复色光，白光就是一种复色光。","path":"26_科技汉语中级教程/05_第五单元 光_第二节 光的折射与色散.txt","line":"15","textbook":"26_科技汉语中级教程","lesson":"05_第五单元 光_第二节 光的折射与色散"},{"sentence":"(sz) 力的分解：实际生活中，我们不仅仅需要求力的合成，有时也需要把一个力分解为几个力，这几个力的作用效果与原来的那个力的作用效果相同，这几个力就叫作分力。力的分解是力的合成的逆过程。","path":"07_物理精讲精练/03_第一章 力_第三节_力的合成与分解.txt","line":"5","textbook":"07_物理精讲精练","lesson":"03_第一章 力_第三节_力的合成与分解"}],"evidenceUnit":"original_source_line"},{"id":"ANT:c9af94f1177f2975","words":["分解","化合"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2163,"first":"分解","second":"化合"},{"line":2917,"first":"化合","second":"分解"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在高温、高压和有催化剂存在的条件下，氮气与氢气可以直接化合，生成氨，并放出热量；同时，氨也会分解成氮气和氢气。这个反应是个可逆反应。","path":"03_化学专业汉语科技汉语系列_clean_v3/09_氮族元素.txt","line":"14","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"09_氮族元素"},{"sentence":"物质是由分子组成的，分子又是由原子组成的。加热氧化铜，会得到铜和氧气。这是因为氧化铜分子分解成了铜原子和氧原子，两个氧原子结合成一个氧分子。这种反应叫做分解反应。在空气中镁条燃烧会发出耀眼的光，并生成一种白色粉末。这种白色粉末是镁和空气中的氧化合生成的氧化镁。这种反应叫做化合反应。","path":"14_基础科技汉语阅读/13_第十三课_分子和原子_02_单质和化合物.txt","line":"4","textbook":"14_基础科技汉语阅读","lesson":"13_第十三课_分子和原子_02_单质和化合物"}],"evidenceUnit":"original_source_line"},{"id":"ANT:db0d8f2a3d3a567e","words":["无机","有机"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6263,"first":"无机","second":"有机"},{"line":7210,"first":"有机","second":"无机"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"化学被划分为“无机化学”和“有机化学”两个领域。这种划分是从世纪后半叶开始的。当时的化学家把动植物自身产生的物质以及利用这些物质生产的酒和染料等“由生物得到的物质”统称为“有机物”，并把有机物之外的其他物质如岩石、水、铁和金等统称为“无机物”。","path":"24_科技汉语阅读教程/33_无机化学与有机化学.txt","line":"2","textbook":"24_科技汉语阅读教程","lesson":"33_无机化学与有机化学"}],"evidenceUnit":"original_source_line"},{"id":"ANT:63d9f9062ba6fdec","words":["无形","有形"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6255,"first":"无形","second":"有形"},{"line":7303,"first":"有形","second":"无形"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"硬件有形，有色，看得见，摸得着。而软件无形，无色，看不见，摸不着。软件的正确与否，是好是坏，要在机器上运行后才能知道。","path":"28_新编科技汉语高级阅读教程/03_第三单元 软件面面观_01_课文.txt","line":"6","textbook":"28_新编科技汉语高级阅读教程","lesson":"03_第三单元 软件面面观_01_课文"}],"evidenceUnit":"original_source_line"},{"id":"ANT:809c1b4d19174c83","words":["无效","有效"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6257,"first":"无效","second":"有效"},{"line":7305,"first":"有效","second":"无效"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"所谓安慰剂效应，是指医生在理论指导下有意识地患者进行了无效治疗，但患者却自以为得到了有效治疗，从而感到轻松，甚至使病情得到一定缓解。","path":"30_中级汉语分类阅读科技篇II/55_神秘_揭开巫术的神秘面纱.txt","line":"9","textbook":"30_中级汉语分类阅读科技篇II","lesson":"55_神秘_揭开巫术的神秘面纱"}],"evidenceUnit":"original_source_line"},{"id":"ANT:01c8478390ff575f","words":["无关","有关"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6264,"first":"无关","second":"有关"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"从排列组合的定义可以知道，排列与元素的顺序有关，而组合与元素的顺序无关。","path":"09_数学专业汉语科技汉语系列_clean_v3/08_第八单元  排列、组合和二项式定理.txt","line":"129","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"08_第八单元  排列、组合和二项式定理"},{"sentence":"重力做功的特点：重力做功与路径无关，只与物体起点和终点位置的高度差有关。","path":"06_物理专业汉语科技汉语系列_clean_v3/05_机械能_第三节_势能.txt","line":"19","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"05_机械能_第三节_势能"},{"sentence":"我们先来看重力做功的特点：重力做功与路径无关，只与物体起点和终点位置的高度差有关。将一个物体向上抛出，我们来分析其上升和下落过程中重力做功与重力势能的变化，如图所示。","path":"06_物理专业汉语科技汉语系列_clean_v3/05_机械能_第三节_势能.txt","line":"12","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"05_机械能_第三节_势能"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8e3fc21691169088","words":["相反","相同"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6812,"first":"相同","second":"相反"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"因为原子是电中性的，所以原子核所带的电荷和核外电子所带电荷应该是大小相同，符号相反。核电荷数等于核内质子数等于核外电子数","path":"03_化学专业汉语科技汉语系列_clean_v3/03_基本概念和基本理论.txt","line":"22","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"03_基本概念和基本理论"},{"sentence":"电流能够产生磁场，而磁场对电流又有力的作用。那么电流和电流之间自然应该通过磁场发生作用。下面我们用实验验证这一设想，如图所示。两条平行直导线，当通以相同方向的电流时，它们相互吸引；当通以相反方向的电流时，它们相互排斥。这时每个电流都处在另一个电流的磁场里，因而受到磁场力的作用。也就是说，电流和电流之间，就像磁极和磁极之间一样，也会通过磁场发生相互作用。","path":"06_物理专业汉语科技汉语系列_clean_v3/08_磁场_第一节_磁场 安培定律.txt","line":"10","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"08_磁场_第一节_磁场 安培定律"},{"sentence":"正电荷受到的电场力方向与电场强度方向相同，负电荷受到的电场力方向与电场强度方向相反。","path":"07_物理精讲精练/21_第六章 电 场_第二节_电场与电场强度.txt","line":"5","textbook":"07_物理精讲精练","lesson":"21_第六章 电 场_第二节_电场与电场强度"}],"evidenceUnit":"original_source_line"},{"id":"ANT:259ee7231e2b8d8c","words":["一样","不同"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":786,"first":"不同","second":"一样"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"不过后来，人们发现菜布尼茨和牛顿使用的方法和途径均不一样，对微积分学的贡献也不同。","path":"02_理工中文/02_第二章极限的奥妙_04_函数是用来描述变量之间的关系的概念。.txt","line":"23","textbook":"02_理工中文","lesson":"02_第二章极限的奥妙_04_函数是用来描述变量之间的关系的概念。"},{"sentence":"牛顿是一名非常著名的科学家，在自然科学史上占有独特的地位，但大多数时候，他是以一位伟大的物理学家的形象存在于人们的心中。其实，牛顿除了在物理学上有所建树之外，还有另一项重大发明，那就是微积分。不过，牛顿对物理和数学两个方面的贡献并不是各自独立的，而是互相联系的。可以说，牛顿最终是为了总结物体的力学运动规律而创造发明了微积分。和牛顿共享微积分发明权的还有著名的德国数学家菜布尼茨。莱布尼茨在对几何的研究中，开始独立创建微积分。不过由于菜布尼茨和牛顿在创建微积分过程中使用的方法和途径均不一样，对微积分学的贡献也不同，如今学术界将微积分的发明权判定为他们两人共同享有。","path":"02_理工中文/02_第二章极限的奥妙_05_能力拓展.txt","line":"2","textbook":"02_理工中文","lesson":"02_第二章极限的奥妙_05_能力拓展"},{"sentence":"由此可见，不同颜色的物体转为灰色时，亮度是不一样的。","path":"02_理工中文/08_第八章机器视觉_02_相机镜头光学中的疑难问题.txt","line":"20","textbook":"02_理工中文","lesson":"08_第八章机器视觉_02_相机镜头光学中的疑难问题"}],"evidenceUnit":"original_source_line"},{"id":"ANT:5a5587408173165a","words":["无限","有限"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6258,"first":"无限","second":"有限"},{"line":7306,"first":"有限","second":"无限"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"从图形的构造过程中，我们可以了解雪花曲线的自相似性。其实，雪花曲线的神奇不仅在于它的自相似性，我们作出初始三角形的外接圆，可以发现雪花曲线永远不会超出这个圆，也就是说雪花曲线围成的面积是有限的。如果再告诉你，雪花曲线的周长是无限长的，也就是说用一个无限长的图形围成一个有限的面积，是不是有点儿难以置信？","path":"02_理工中文/01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密.txt","line":"5","textbook":"02_理工中文","lesson":"01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密"},{"sentence":"在芝诺之后，阿基米德对这个悖论进行了非常详细的研究。他把每次追赶的路程加起来，计算阿基里斯和乌龟到底跑了多远，并将这个问题归结为无穷级数求和的问题，证明了尽管路程可以无限分割，但整个追赶过程是在一个有限的长度中。","path":"02_理工中文/02_第二章极限的奥妙_02_阿基里斯能追上乌龟吗？.txt","line":"6","textbook":"02_理工中文","lesson":"02_第二章极限的奥妙_02_阿基里斯能追上乌龟吗？"},{"sentence":"数列是一组有序的数，它可能有有限的项，也可能有无穷项，其中有无穷项的数列叫作无穷数列。我们已经学过把有限的数列各项加起来并计算结果，即数列的求和。把无限的数列各项加起来并计算结果的过程，叫作求级数。我们在求级数，即把无限的数列各项加起来时会发现，有的数列之和可能是无穷大的，有的数列之和会趋近于一个数。这是求级数的时候会遇到的两种不同的情况。它们分别是级数的发散和收敛性质。","path":"02_理工中文/03_第三章数列与级数_04_大自然中很多现象都遵循斐波那契数列的规律。.txt","line":"2","textbook":"02_理工中文","lesson":"03_第三章数列与级数_04_大自然中很多现象都遵循斐波那契数列的规律。"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0493b22e1338dab7","words":["不等","相等"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":845,"first":"不等","second":"相等"},{"line":6823,"first":"相等","second":"不等"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"实验表明，用同一种材料制成的横截面积相等而长度不等的导体，电阻跟导体的长度成正比；长度相等而横截面积不等的导体，电阻跟导体的横截面积成反比。","path":"06_物理专业汉语科技汉语系列_clean_v3/07_直流电路_第一节_电路与欧姆定律.txt","line":"35","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"07_直流电路_第一节_电路与欧姆定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:5f73602082b01bf6","words":["反比","正比"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2307,"first":"反比","second":"正比"},{"line":7958,"first":"正比","second":"反比"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"物体的加速度跟作用力成正比，跟物体的质量成反比，且加速度的方向与引起这个加速度的力的方向相同。","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第二节_牛顿第二定律.txt","line":"17","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第二节_牛顿第二定律"},{"sentence":"上面的结论是物体受到一个力作用时的情况。当物体同时受到几个力作用时，上述关系可推广为：物体的加速度跟所受的合力成正比，跟物体的质量成反比，加速度的方向跟合力的方向相同。即：","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第二节_牛顿第二定律.txt","line":"20","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第二节_牛顿第二定律"},{"sentence":"在真空中的两个点电荷之间的相互作用力跟它们的电荷量的乘积成正比，跟它们之间的距离的平方成反比，作用力的方向在它们的连线上。","path":"06_物理专业汉语科技汉语系列_clean_v3/06_电场_第一节_电荷与库伦定律.txt","line":"23","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"06_电场_第一节_电荷与库伦定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:afc540e209ec1c52","words":["反比例","正比例"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":8429,"first":"反比例","second":"正比例"},{"line":8693,"first":"正比例","second":"反比例"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"几种常见函数有一次函数、二次函数、正比例函数、反比例函数、三角函数（正弦函数、余弦函数、正切函数、余切函数）、对数函数、指数函数等。","path":"18_科技汉语基础篇/02_函数及其图像_01_课文.txt","line":"4","textbook":"18_科技汉语基础篇","lesson":"02_函数及其图像_01_课文"},{"sentence":"我们已经知道，sz是正比例函数，sz⁻¹（即sz）是反比例函数，sz是二次函数。从形式上看，这几个函数只是指数不同。如果一个函数，底数是自变量x，指数是常量a，即szᵃ，这样的函数称为幂函数。","path":"26_科技汉语中级教程/03_第三单元 函数_其他.txt","line":"3","textbook":"26_科技汉语中级教程","lesson":"03_第三单元 函数_其他"}],"evidenceUnit":"original_source_line"},{"id":"ANT:4090581d21a89064","words":["偶数","奇数"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4692,"first":"偶数","second":"奇数"},{"line":5231,"first":"奇数","second":"偶数"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"但有一些数字是无穷的，比数学家无论花费多少时间所记录的数字都大。比如，所有的数字有多少？一条直线上存在多少个点？它们显然是无穷的。那么在无法被公式表达的情况下，如何描述其大小？德国数学家康托尔提出，所有数字的数量更大还是一条线上点的数量更大？这个问题探讨了无穷数之间的关系。他认为要比较两个无穷数的大小，可以将它们进行配对，在两个无穷数集合中，其中一个集合的每一个元素都可与另一个集合的每个元素搭配成一对，到最后两个集合中都没有剩余的元素，那么代表这两个集合的无穷数就是相等的。若其中一个集合中的元素有剩余，我们就可以说代表这个集合的无穷数比另一个更大或更强。以所有奇数和所有偶数构成的两个无穷数列作为例子，运用上述方法建立奇数数列与偶数数列的对应关系。","path":"02_理工中文/03_第三章数列与级数_01_神秘的无穷数.txt","line":"5","textbook":"02_理工中文","lesson":"03_第三章数列与级数_01_神秘的无穷数"},{"sentence":"在生产科研的应用上，由于在元素周期表中位置相近元素的化学性质相似，这就启发人们在元素周期表中一定的范围内寻找新的物质。比如特种合金材料的制造，在元素周期表里从ⅢB到ⅥB的过渡元素，是制造特种合金的良好材料，是制造飞机、导弹、火箭等的不可缺少的金属。再比如矿物的寻找，地球上化学元素的分布与它们在元素周期表中的位置有关。科学研究和科学实验发现，原子量较小的元素在地壳中含量较多，原子量较大的元素在地壳中含量较少；奇数原子序数的元素较少，偶数原子序数的元素较多。这对矿物的寻找有指导意义。","path":"23_科技汉语简明教程/03_元素周期律和元素周期表_课文.txt","line":"10","textbook":"23_科技汉语简明教程","lesson":"03_元素周期律和元素周期表_课文"},{"sentence":"偶数和奇数：在整数中，能被sz整除的数是偶数，不能被sz整除的数是奇数。在口语中有时把偶数称为双数，把奇数称为单数。","path":"26_科技汉语中级教程/03_第三单元 函数_其他.txt","line":"35","textbook":"26_科技汉语中级教程","lesson":"03_第三单元 函数_其他"}],"evidenceUnit":"original_source_line"},{"id":"ANT:e4172a7da4a9286d","words":["变量","常量"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":921,"first":"变量","second":"常量"},{"line":1564,"first":"常量","second":"变量"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在生产和科学实验中，我们常遇到常量和变量。变量是数学分析研究的基本对象。在一些具体问题中，往往存在两个或两个以上的变量。变量之间的关系常用函数来表示。我们看下面两个例子。","path":"16_基础科技汉语教程听力课本/52_一次函数与直线方程.txt","line":"2","textbook":"16_基础科技汉语教程听力课本","lesson":"52_一次函数与直线方程"},{"sentence":"极限法揭示了变量与常量、无限与有限的对立统一关系，是唯物辩证法的对立统一规律在数学领域中的应用。借助极限法，人们可以从“有限”认识“无限”，从“不变”认识“变”，从“直线形”认识“曲线形”，从“量变”认识“质变”，从“近似”认识“准确”。","path":"28_新编科技汉语高级阅读教程/01_第一单元 多元函数_03_极限法.txt","line":"9","textbook":"28_新编科技汉语高级阅读教程","lesson":"01_第一单元 多元函数_03_极限法"},{"sentence":"上述定义仅适用于代数函数的范围，而对数函数、指数函数、三角函数等，都是随着数学研究的深入，人们逐渐定义出的“超越函数”，即：超出了代数函数范围的函数。在一些数学家看来，“代数函数”和“超越函数”的区别仅仅在于“超越函数”无限多次重复了“代数函数”的运算。因此，函数的概念得到进一步扩展，被定义为：“函数是指由一个变量与一些常量，通过任何方式（有限的或无限的）形成的解析表达式。”","path":"28_新编科技汉语高级阅读教程/01_第一单元 多元函数_02_函数的历史.txt","line":"4","textbook":"28_新编科技汉语高级阅读教程","lesson":"01_第一单元 多元函数_02_函数的历史"}],"evidenceUnit":"original_source_line"},{"id":"ANT:9b4483c0c8af4399","words":["宏观","微观"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2993,"first":"宏观","second":"微观"},{"line":6330,"first":"微观","second":"宏观"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"温度：在宏观上表示物体的冷热程度；在微观上是分子平均动能的标志。","path":"06_物理专业汉语科技汉语系列_clean_v3/11_热学_第二节_理想气体状态方程.txt","line":"11","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"11_热学_第二节_理想气体状态方程"},{"sentence":"温度：温度在宏观上表示物体的冷热程度；在微观上是分子平均动能的标志。","path":"06_物理专业汉语科技汉语系列_clean_v3/11_热学_第一节_分子.txt","line":"28","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"11_热学_第一节_分子"},{"sentence":"大到星系的宏观系统，小至原子、基本粒子的微观系统，动量守恒定律都是适用的。正是因为这样，动量守恒定律成为人们认识自然、改造自然的重要工具。","path":"16_基础科技汉语教程听力课本/58_动量守恒定律.txt","line":"11","textbook":"16_基础科技汉语教程听力课本","lesson":"58_动量守恒定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:5f62787ac0e86ea1","words":["相对","绝对"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6822,"first":"相对","second":"绝对"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"与普通电容器相比，超级电容器具有更高的介电常数〔介质在外加电场时会产生感应电荷使电场变弱，原外加电场（真空中）与最终介质中的电场的比值即为介电常数。相对介电常数×真空中绝对介电常数=介电常数〕或者更大的面积。例如，陶瓷超级电容器具有相当高的抗压水平和绝缘强度，这使它们可能成为未来储能应用的方案。","path":"02_理工中文/09_第九章未来电网_02_储能技术.txt","line":"25","textbook":"02_理工中文","lesson":"09_第九章未来电网_02_储能技术"},{"sentence":"自然界中一切物体都在运动，绝对静止的物体是不存在的。在机械运动中，我们所描述的物体的运动和静止都是相对的。如果物体 A 相对于物体 B 的位置没有发生变化，则称物体是静止的；如果物体 A 相对于物体 B 的位置发生了变化，则称物体是运动的。可见，要描述一个物体的运动，首先要选定某个其他物体做参考，观察物体相对于这个“其他物体”的位置是否随时间变化，以及怎样变化。这种用来做参考的物体称为参考系。","path":"26_科技汉语中级教程/06_第六单元 运动_第一节 机械运动.txt","line":"11","textbook":"26_科技汉语中级教程","lesson":"06_第六单元 运动_第一节 机械运动"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8aa1d00cd0a56a86","words":["具体","抽象"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1368,"first":"抽象","second":"具体"},{"line":13173,"first":"具体","second":"抽象"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"数学定理与物理定律的互变亦即抽象与具体的互变。","path":"20_科技汉语读写教程/13_变换解释（说明）.txt","line":"6","textbook":"20_科技汉语读写教程","lesson":"13_变换解释（说明）"},{"sentence":"说明某些抽象的或者是人们比较陌生的事物，可以用具体的或者大家已经熟悉的事物和它比较，使读者通过比较得到具体而鲜明的印象，事物的特征也往往在比较中显现出来。这种方法叫做比较。如：","path":"17_汉语科技文选读/05_生物世界_第5课.txt","line":"48","textbook":"17_汉语科技文选读","lesson":"05_生物世界_第5课"},{"sentence":"函数的概念最早来源于对运动的研究。例如，伽利略把函数关系描述为：“从静止状态开始以定常加速度下降的物体，其经过的距离与所用时间的平方成正比”；“沿着同高度但不同坡度的倾斜平板下滑的物体，其下滑的时间与平板的长度成正比”。我们可以用数学形式来表述这两个函数关系。把这些具体的函数作为原型，sz世纪的一些数学家将函数概念抽象定义为：“函数是这样一个量，它是从一些其他的量通过一系列代数运算而得到的。”","path":"28_新编科技汉语高级阅读教程/01_第一单元 多元函数_02_函数的历史.txt","line":"3","textbook":"28_新编科技汉语高级阅读教程","lesson":"01_第一单元 多元函数_02_函数的历史"}],"evidenceUnit":"original_source_line"},{"id":"ANT:522c742629d8cf4e","words":["直接","间接"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3583,"first":"间接","second":"直接"},{"line":7901,"first":"直接","second":"间接"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"研究发现，人类所需能量的绝大部分都直接或间接地来自太阳。自然界里的各种植物通过光合作用把太阳能转化成了化学能，并在体内贮存下来，这些能量给人类和动物提供了能源。","path":"16_基础科技汉语教程听力课本/44_能源.txt","line":"7","textbook":"16_基础科技汉语教程听力课本","lesson":"44_能源"},{"sentence":"利用太阳的辐射能，使水或其他介质经过装置系统，直接或间接地转换成电能，就是太阳能发电。目前有两种基本途径：一种是把太阳光辐射能转化为热能，例如，采用反射镜把阳光聚集起来加热水或其他介质，利用产生的蒸气推动涡轮机运转，再带动发电机发电；另一种是通过光电器件将太阳能直接转换为电能，在人造卫星和宇宙飞船上采用的太阳能电池，就是这种。","path":"16_基础科技汉语教程听力课本/33_太阳能.txt","line":"6","textbook":"16_基础科技汉语教程听力课本","lesson":"33_太阳能"},{"sentence":"研究发现，人类所需能量的绝大部分都直接或间接地来自太阳。自然界里的各种植物通过光合作用把太阳能转化成了化学能，并在体内贮存下来，这些能量给人类和动物提供了能源。煤炭、石油、天然气都是化石燃料，它们是由古代埋在地下的动植物经过漫长的年代转化形成的，这其实是由古代生物固定下来的太阳能。目前，化石能源仍是世界上的主要能源，在世界能源供应中约占。另外，水能、风能等也都是由太阳能转换来的。","path":"16_基础科技汉语教程听力课本/43_不倒翁的奥秘.txt","line":"10","textbook":"16_基础科技汉语教程听力课本","lesson":"43_不倒翁的奥秘"}],"evidenceUnit":"original_source_line"},{"id":"ANT:920f5522c0a59855","words":["复杂","简单"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2031,"first":"复杂","second":"简单"},{"line":3542,"first":"简单","second":"复杂"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"你去爬山时一定注意过山坡的形状，有的简单，有的复杂，或高或低，或平或陡。但无论哪种形状，山坡的高度总是随着行进者离出发点距离的变化而变化。有的部分很陡，也就是说高度变化得很快；而另一些部分比较平坦，高度变化得慢，或者几乎不变。我们可以用一个叫坡度的概念来描述高度的这种变化。坡度定义为高度的增加量与你走过的水平距离的比值。比如，如果像图所示的简单形状，用初等数学中的简单几何知识就能描述。","path":"02_理工中文/02_第二章极限的奥妙_01_微积分与极限思想.txt","line":"5","textbook":"02_理工中文","lesson":"02_第二章极限的奥妙_01_微积分与极限思想"},{"sentence":"如果主链上有相同的取代基，将取代基合并起来，用“二、三”等数字表示，在用于表示取代基位置的阿拉伯数字之间要用“，”号隔开；如果主链上有几个不同的取代基，就把简单的写在前面，把复杂的写在后面。","path":"03_化学专业汉语科技汉语系列_clean_v3/15_烃.txt","line":"29","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"15_烃"},{"sentence":"简单来说，微积分是高等数学中研究函数的数学分支，它可以通过计算函数的导数来考察函数变化的快慢。比如像图的情况，计算坡度时只需要用这一段山坡高度的变化除以水平距离的变化就可以了。但是当函数图像的形状是个复杂的不规则曲线时，斜率的计算也变得很复杂，这时候，微积分就派上用场了。在日常生活中，复杂的函数图像有很多，比如，图所示的股票市场涨落、温度、相对湿度、气压变化等，这些曲线都可以用微积分来分析。","path":"02_理工中文/02_第二章极限的奥妙_01_微积分与极限思想.txt","line":"7","textbook":"02_理工中文","lesson":"02_第二章极限的奥妙_01_微积分与极限思想"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f7d5b642e3837342","words":["正确","错误"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1224,"first":"错误","second":"正确"},{"line":7937,"first":"正确","second":"错误"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"判断下列说法是否正确，并改正错误的说法。","path":"20_科技汉语读写教程/21_问题解读（二）.txt","line":"24","textbook":"20_科技汉语读写教程","lesson":"21_问题解读（二）"},{"sentence":"判断下列说法正确与否，如果错误，请加以改正。","path":"22_科技汉语听说教程/20_问题解读.txt","line":"19","textbook":"22_科技汉语听说教程","lesson":"20_问题解读"},{"sentence":"用语言、数学符号或式子表达的，可以判断正误的陈述句叫做命题。其中，正确的陈述句叫做真命题，错误的陈述句叫做假命题。","path":"09_数学专业汉语科技汉语系列_clean_v3/02_第二单元 简单的逻辑.txt","line":"7","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"02_第二单元 简单的逻辑"}],"evidenceUnit":"original_source_line"},{"id":"ANT:ce7bb18a951479a8","words":["异常","正常"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7373,"first":"异常","second":"正常"},{"line":7957,"first":"正常","second":"异常"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"元素含量低于sz，且是生物体必需的一些元素，称作微量元素。微量元素的重要性主要体现在维持正常人体机能、维持人的心理健康和预防疾病几方面。微量元素虽然在身体里的含量不多，但是和人的生存与健康关系密切。如果微量元素摄入过量、不平衡或缺乏都会不同程度地引起人体生理的异常或引发疾病，甚至影响人的生命。目前，比较明确的是约sz的疾病直接是由微量元素缺乏或不平衡导致的。","path":"02_理工中文/15_第十五章化学元素知多少_03_人体中的化学元素.txt","line":"4","textbook":"02_理工中文","lesson":"15_第十五章化学元素知多少_03_人体中的化学元素"}],"evidenceUnit":"original_source_line"},{"id":"ANT:dbecbfc7a1dd41e5","words":["光滑","粗糙"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1242,"first":"粗糙","second":"光滑"},{"line":2388,"first":"光滑","second":"粗糙"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"抚摸塑料袋的表面，感觉光滑的是无毒塑料袋；粗糙不平的是有毒塑料袋。","path":"27_新编科技汉语中级阅读教程/02_阅读3教你识别有毒无毒塑料袋.txt","line":"6","textbook":"27_新编科技汉语中级阅读教程","lesson":"02_阅读3教你识别有毒无毒塑料袋"},{"sentence":"第四点，口罩的正反面颜色一般是不同的，外面那一层一般是浅蓝色或者深颜色，里面那一层一般是白色；最后，通过面料区分，根据光滑程度来看，口罩朝外的部分因为阻隔水，是比较光滑的，朝内的部分由比较透气的网状组织制作而成，是比较粗糙的。","path":"02_理工中文/13_第十三章公共卫生危机处理_04_大自然中有很多微生物。.txt","line":"13","textbook":"02_理工中文","lesson":"13_第十三章公共卫生危机处理_04_大自然中有很多微生物。"}],"evidenceUnit":"original_source_line"},{"id":"ANT:ceb06d249bd8e016","words":["干燥","潮湿"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1476,"first":"潮湿","second":"干燥"},{"line":2702,"first":"干燥","second":"潮湿"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"一是如果气温持续升高，会导致南北两极水的融化和冰川的消融。这些冰雪融水注入海洋，会使海平面升高，因此中国沿海城市和世界上的其他一些海滨城市，将被海水淹没，成为“海底世界”。自然环境、生态系统和人类的文明将遭到破坏。地表也将发生变化，一些地方会变干燥，而另一些地方会变潮湿，疾病开始蔓延，一些名胜古迹将不存在。","path":"15_基础科技汉语教程阅读课本下/46_02_全球变暖的后果.txt","line":"4","textbook":"15_基础科技汉语教程阅读课本下","lesson":"46_02_全球变暖的后果"},{"sentence":"铜在干燥的空气中化学性质不活泼，在潮湿的空气中，表面可以生成碱式碳酸铜。","path":"03_化学专业汉语科技汉语系列_clean_v3/14_几种常见的金属.txt","line":"75","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"14_几种常见的金属"},{"sentence":"高压的控制，雨水很少，气候干燥，比如撒哈拉大沙漠；或者是在大陆内部，离海遥远，潮湿的海洋气团无法到达，气候干旱，比如塔克拉玛干沙漠。","path":"23_科技汉语简明教程/05_地质地貌_课文.txt","line":"5","textbook":"23_科技汉语简明教程","lesson":"05_地质地貌_课文"}],"evidenceUnit":"original_source_line"},{"id":"ANT:2f8007e70d4b50cf","words":["干燥","湿润"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2702,"first":"干燥","second":"湿润"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"但对燕子来说，全球升温并不总是好事。气候变暖使有湿润土壤的地域变得干燥，燕子穿过撒哈拉沙漠和广阔的非洲大陆时，由于缺乏合适的停留点可能导致死亡率上升，因而数量全面下降。","path":"17_汉语科技文选读/03_生物世界_第3课.txt","line":"10","textbook":"17_汉语科技文选读","lesson":"03_生物世界_第3课"},{"sentence":"因此，氯水中存在多种分子和离子，主要有：氯气、次氯酸、水、氯离子、氢离子和次氯酸根离子。次氯酸具有强氧化性，可以将有色物质氧化成无色物质，因此具有漂白性。由于氯气和水生成次氯酸，所以湿润的氯气也具有漂白性，但是干燥的氯气是没有漂白性的。","path":"03_化学专业汉语科技汉语系列_clean_v3/06_卤素.txt","line":"16","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"06_卤素"},{"sentence":"在英国，燕子常常只产两胎，产三胎的可谓少之又少。气候干燥、阳光充足的天气会产生很多飞虫，这意味着它们能为幼鸟提供食物来源，以便它们很快地发育和长出羽毛。因此，在一个温暖湿润的夏季后，英国的燕子可能只独养一胎；而如果在一个持续的温暖干燥的夏天，它们则会尝试产两胎或三胎。","path":"17_汉语科技文选读/03_生物世界_第3课.txt","line":"8","textbook":"17_汉语科技文选读","lesson":"03_生物世界_第3课"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3e8ad13d1297cf51","words":["浑浊","清澈"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2750,"first":"浑浊","second":"清澈"},{"line":4992,"first":"清澈","second":"浑浊"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"不管白天还是黑夜、水质清澈还是浑浊，海豚都能准确地捕捉到鱼。这是因为海豚具有超声波探测和导航的本领。海豚没有声带，它的声源就是它头部内的瓣膜和气囊系统。海豚把空气吸入气囊系统，空气流过瓣膜的边缘发生振动，就会发出超声波。海豚的头部还有“脂肪瘤”，它","path":"14_基础科技汉语阅读/25_第二十五课_海豚与潜艇声纳系统_01_海豚与潜艇声纳系统.txt","line":"4","textbook":"14_基础科技汉语阅读","lesson":"25_第二十五课_海豚与潜艇声纳系统_01_海豚与潜艇声纳系统"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0de3edda4c6056c3","words":["密集","稀疏"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4367,"first":"密集","second":"稀疏"},{"line":6983,"first":"稀疏","second":"密集"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"所示的波中，质点上下振动，波向右传播，二者的方向是垂直的。质点的振动方向与波传播方向垂直的波，叫作横波。在横波中，凸起的最高处叫作波峰，凹下的最低处叫作波谷。现在我们来看另一种波。在光滑的水平桌面上，放一根长而软的螺旋弹簧，用手拉住弹簧的左端，有规律的左右振动，可以看到弹簧上产生密集的部分和稀疏的部分。这种密集部分和稀疏部分相间的自左向右传播，在弹簧上形成一列波。我们可以把弹簧看作一列由弹力联系着的质点，手拉弹簧左右振动起来以后，以此带动后面的点左右振动，但后一个质点总比前一个质点迟一些振动，从整体上看形成疏密相间的波在弹簧上传播","path":"06_物理专业汉语科技汉语系列_clean_v3/10_机械振动和机械波_第三节_机械波.txt","line":"15","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"10_机械振动和机械波_第三节_机械波"},{"sentence":"(sz) 电场线越稀疏的地方，电场强度越小；电场线越密集的地方，电场强度越大。","path":"07_物理精讲精练/21_第六章 电 场_第二节_电场与电场强度.txt","line":"9","textbook":"07_物理精讲精练","lesson":"21_第六章 电 场_第二节_电场与电场强度"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0c1d05148b675b98","words":["低温","高温"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1824,"first":"低温","second":"高温"},{"line":2624,"first":"高温","second":"低温"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"橡胶是制造飞机、军舰、汽车、拖拉机、收割机、水利排灌机械、医疗器械等所必需的材料。根据来源不同，橡胶可以分为天然橡胶和合成橡胶。合成橡胶是以石油、天然气中的二烯烃和烯烃为原料制成的高分子。合成橡胶一般在性能上不如天然橡胶全面，但它具有高弹性、绝缘性、气密性、耐油、耐高温或低温等性能，因而广泛应用于工农业、国防、交通及日常生活中。","path":"03_化学专业汉语科技汉语系列_clean_v3/18_合成材料.txt","line":"47","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"18_合成材料"},{"sentence":"许多物质都有热胀冷缩的性质，为什么人们选用水银和酒精做测温物质呢？原来，要使温度计具有实用价值，要求测温物质应当具有两大特性：一是测温物质随温度变化体积改变必须很灵敏，这样可以测量极微小的温度变化；二是在低温下测量温度时，测温物质不能凝固成固体，反之，在高温下，测温物质也不能变成气体。水银或酒精具有以上特性，这就是温度计用水银或酒精而不用其他物质标示温度的原因。","path":"16_基础科技汉语教程听力课本/21_水银温度计和酒精温度计.txt","line":"5","textbook":"16_基础科技汉语教程听力课本","lesson":"21_水银温度计和酒精温度计"},{"sentence":"室外机箱组合了制冷系统中的压缩机、冷凝器和风机等。室外机箱里有制冷剂。空调器开动后，压缩机将这种制冷剂压缩成高温高压的蒸气，然后送到冷凝器。同时，风机再不断地吸入室外的空气，并使这些空气迅速流过冷凝器，制冷剂便在冷凝器中不断地散发热量降低温度，吸入的室外空气被变热后排出去，而制冷剂在冷凝器中被冷凝成高压液体。这种高压低温的液体被输送到室内机箱的蒸发器中。这时，室内的空气被离心风扇吸进去，穿过蒸发器，蒸发器中的制冷剂随之蒸发并吸收周围的热量，使进来的室内空气降温成为冷风，再经过风道从出口吹到室内；制冷剂蒸发成气体后被送回室外机，再次被压缩机压缩成高温高压的蒸气。这样循环往复，室内的温度就自然降低，使人觉得凉快了。","path":"16_基础科技汉语教程听力课本/51_空调是怎样制冷的.txt","line":"4","textbook":"16_基础科技汉语教程听力课本","lesson":"51_空调是怎样制冷的"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f99561b7a3200506","words":["低压","高压"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1822,"first":"低压","second":"高压"},{"line":2622,"first":"高压","second":"低压"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"万吨水压机采用了六个工作缸，这样大活塞的总面积就比较大了；每个缸里水的压强都是sz个大气压。这样的高压水又是怎样得来的呢？水压机所用的工作水来源于互相连通的低压容器和水箱，里面的压强为大气压强。低压水进入高压水泵，经过加压后进入高压容器。再利用空气压缩机加压，推动其流入主缸和升降缸。加压后的水就变成了压强为sz个大气压的高压水。","path":"12_基础科技汉语教程听说课本上/10_水压机的工作原理.txt","line":"10","textbook":"12_基础科技汉语教程听说课本上","lesson":"10_水压机的工作原理"}],"evidenceUnit":"original_source_line"},{"id":"ANT:1291816888673534","words":["低速","高速"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1826,"first":"低速","second":"高速"},{"line":2626,"first":"高速","second":"低速"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"sz.经典力学是对宏观物体和低速物体进行的力学研究，量子力学是对微观物体和高速物体的力学研究。","path":"02_理工中文/10_第十章知量子探世界_04_量子是微观世界中物质的运动形式。.txt","line":"19","textbook":"02_理工中文","lesson":"10_第十章知量子探世界_04_量子是微观世界中物质的运动形式。"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8328e3acee4687d3","words":["省力","费力"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5802,"first":"省力","second":"费力"},{"line":13848,"first":"费力","second":"省力"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"动力臂大于阻力臂的杠杆叫做省力杠杆；动力臂小于阻力臂的杠杆叫做费力杠杆；动力臂等于阻力臂的杠杆叫做等臂杠杆。","path":"26_科技汉语中级教程/07_第七单元 力和简单机械_第三节 简单机械.txt","line":"11","textbook":"26_科技汉语中级教程","lesson":"07_第七单元 力和简单机械_第三节 简单机械"}],"evidenceUnit":"original_source_line"},{"id":"ANT:1b85e54c33c69784","words":["浓缩","稀释"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4567,"first":"浓缩","second":"稀释"},{"line":6984,"first":"稀释","second":"浓缩"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"烧杯：配制、浓缩、稀释溶液；反应器；水浴加热；加热液体。加热时垫石棉网。盛装液体不超过容量的三分之二，加热时不超过二分之一。","path":"03_化学专业汉语科技汉语系列_clean_v3/18_合成材料.txt","line":"56","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"18_合成材料"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8ea9d66332c4e45b","words":["波峰","波谷"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":868,"first":"波谷","second":"波峰"},{"line":869,"first":"波峰","second":"波谷"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在横波中波长等于相邻两个波峰或波谷之间的距离；在纵波中波长等于相邻两个密部或疏部的中央之间的距离。","path":"06_物理专业汉语科技汉语系列_clean_v3/10_机械振动和机械波_第四节_波长、频率和波速.txt","line":"7","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"10_机械振动和机械波_第四节_波长、频率和波速"},{"sentence":"跟水波一样，光波也有波峰和波谷。当波峰和波峰相遇的时候，波峰就会加强；当波谷和波谷相遇的时候，波谷就会加强。加强的地方就显得明亮。反之，当波峰和波谷相遇的时候，光波就会互相消减。","path":"15_基础科技汉语教程阅读课本下/32_01_光的干涉.txt","line":"3","textbook":"15_基础科技汉语教程阅读课本下","lesson":"32_01_光的干涉"},{"sentence":"波的图像表示介质中各质点在某一时刻偏离平衡位置的位移的空间分布情况。在不同时刻质点振动的位移不同，波形也随之改变，不同时刻的波形曲线是不同的。波以一定的速率在介质中传播，单位时间内某一波峰或波谷向前移动的距离等于波速。从某一时刻波的图像可以知道任一时刻波的图像，例如知道某一时刻的波的图像，使波的图像沿着波的传播方向移动，就得到时刻波的图像。图表示经过时间后的波的形状和各质点的位移。","path":"06_物理专业汉语科技汉语系列_clean_v3/10_机械振动和机械波_第三节_机械波.txt","line":"24","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"10_机械振动和机械波_第三节_机械波"}],"evidenceUnit":"original_source_line"},{"id":"ANT:42fcd4cff3cbdc92","words":["终点","起点"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5205,"first":"起点","second":"终点"},{"line":7858,"first":"终点","second":"起点"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"电场线有起点和终点，而磁感线是闭合的，没有起点，也没有终点。","path":"06_物理专业汉语科技汉语系列_clean_v3/08_磁场_第一节_磁场 安培定律.txt","line":"39","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"08_磁场_第一节_磁场 安培定律"},{"sentence":"重力做功的特点：重力做功与路径无关，只与物体起点和终点位置的高度差有关。","path":"06_物理专业汉语科技汉语系列_clean_v3/05_机械能_第三节_势能.txt","line":"19","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"05_机械能_第三节_势能"},{"sentence":"应该注意，电场线和磁感线有着重大的区别。电场线有起点和终点，而磁感线是闭合的，没有起点，也没有终点。","path":"06_物理专业汉语科技汉语系列_clean_v3/08_磁场_第一节_磁场 安培定律.txt","line":"31","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"08_磁场_第一节_磁场 安培定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3d5e8e1f7e245b7c","words":["内部","外部"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4688,"first":"内部","second":"外部"},{"line":6466,"first":"外部","second":"内部"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"圆之所以成为如此受欢迎的几何图形，除了具有“圆满、对称”的特点外，还因为圆具有引申义或者说哲学意义。如图所示，直线上有A、B、C三点，其中B点在A、C两点之间，或者说B点在A、C两点之内。但是如图，把A、B、C三点放在圆上，那么B点在A、C两点之间，也可以说A点在B、C两点之间，或者说C点在A、B两点之间，在圆上分不出内外，没有方向性。这说明圆和直线不一样，圆上的点没有内外之分，每一点既是内部，也是外部，同时圆周上的每一点具有平等性，和圆心距离相等，每一点既是起，点又是终点，你中有我，我中有你。所以，奥林匹克标志的设计者皮埃尔·德·顾拜旦选取五个彼此相连的圆环，以此代表大洲的团结，体现了所有国家、所有民族是一个“奥林匹克大家庭”的主题。","path":"02_理工中文/01_第一章北京冬奥会中的几何美学_04_四边形的长就是圆周长的一半。.txt","line":"17","textbook":"02_理工中文","lesson":"01_第一章北京冬奥会中的几何美学_04_四边形的长就是圆周长的一半。"},{"sentence":"耐寒性植物通常会有两种办法可以避免这种命运的发生。一种办法是为了确保冰块结晶体在细胞组织外部形成而不是内部，它们在叶子上覆盖一层东西，如毛蕊花属的植物种子上的绒毛，可以使使冰块结晶体在其表面形成。另一种办法是在细胞内部积累反冰冻型的化合物（通常为糖类），以降低水的结冰点。","path":"17_汉语科技文选读/07_自然环境与化学物理世界_第7课.txt","line":"12","textbook":"17_汉语科技文选读","lesson":"07_自然环境与化学物理世界_第7课"},{"sentence":"图表示通电螺线管磁场的磁感线分布情况。螺线管通电以后表现出来的磁性，很像是一根条形磁铁，一端相当于北极，另一端相当于南极。改变电流的方向，它的南北极就对调。通电螺线管外部的磁感线和条形磁铁外部的磁感线相似，也是从北极出来，进入南极。通电螺线管内部具有磁场，内部的磁感线跟螺线管的轴线平行，方向由南极指向北极，并和外部的磁感线连接，形成一些环绕电流的闭合曲线。","path":"06_物理专业汉语科技汉语系列_clean_v3/08_磁场_第一节_磁场 安培定律.txt","line":"27","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"08_磁场_第一节_磁场 安培定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3ecfb5d8c887efd6","words":["内层","外层"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4687,"first":"内层","second":"外层"},{"line":6464,"first":"外层","second":"内层"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"眼睛最主要的部分是眼球。眼球壁分三层：外层是白色的巩膜，它有一定的硬度可以保护眼球，就像照相机的外壳；在巩膜的前端，有一部分是透明的,叫角膜；眼球壁的中层为血管膜，由前向后分虹膜、晶状体和脉络膜。透过角膜，我们可以看到虹膜，有人把它叫做“黑眼珠”。虹膜中央有一孔，这就是瞳孔，它可以调节进入眼睛光线的多少。晶状体在虹膜后，就像一个中间厚四周薄的凸透镜，当光线透过角膜进入眼睛后，它把进入的光线会聚在一起，形成图像，然后调节眼球，使图像落在视网膜上。脉络膜像照相机的暗箱一样, 防止光线进入。眼球壁的内层是视网膜，它通过神经与我们的大脑相连。视网膜的细胞对光十分敏感，上亿个感光细胞感到了光的强弱和色彩，并立即通过神经传给大脑，于是，我们就“看”到了那个物体。","path":"14_基础科技汉语阅读/27_第二十七课_数码相机的成像原理_02_为什么眼睛能看见物体?.txt","line":"5","textbook":"14_基础科技汉语阅读","lesson":"27_第二十七课_数码相机的成像原理_02_为什么眼睛能看见物体?"},{"sentence":"例如，由sz与sz复合得到sz，sz是外层函数，sz是内层函数。","path":"09_数学专业汉语科技汉语系列_clean_v3/12_第一单元 函数的极限.txt","line":"156","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"12_第一单元 函数的极限"},{"sentence":"一般地，设函数 sz，sz，当 x 在 sz 的定义域 Dg 中变化时，sz 的值在 sz 的定义域 Df 内变化，因此变量 x 与 y 之间通过变量 u 形成一种函数关系，记为 sz，称为由 sz 与 sz 得到的复合函数，记作 f∘sz，其中称为自变量，u 为中间变量，sz 称为外层函数，sz 称为内层函数。","path":"09_数学专业汉语科技汉语系列_clean_v3/12_第一单元 函数的极限.txt","line":"154","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"12_第一单元 函数的极限"}],"evidenceUnit":"original_source_line"},{"id":"ANT:83ecf09e9b2eb38d","words":["内力","外力"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4672,"first":"内力","second":"外力"},{"line":6452,"first":"外力","second":"内力"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"同一种事物的分类方法各有不同。例如，力的分类方法，有的教材分成两种，有的分成四种。不同的分类方法是因分类的角度不同。如力，按性质（即按产生的原因）分重力、弹力、摩擦力、电磁力等；按效果分为压力、支持力、拉力、动力等；按作用方式分场力、接触力；按研究对象分为内力、外力。","path":"20_科技汉语读写教程/12_分类与举例.txt","line":"21","textbook":"20_科技汉语读写教程","lesson":"12_分类与举例"},{"sentence":"我们再讨论一下动量守恒的条件。通常我们把相互作用的物体的全体叫做系统。例如滑冰的两个人组成一个系统。系统里的每个物体，既可以受到系统内物体的力，也可以受到系统外物体的力，前者叫做内力，后者叫做外力。滑冰的人除了受到相互作用的内力外，都还受到向下的重力和向上的支持力，这个重力和支持力作用在同一个人身上，大小相等、方向相反，合力为零。外力的合力为零或者整个系统不受到外力，就是动量守恒的条件。","path":"16_基础科技汉语教程听力课本/58_动量守恒定律.txt","line":"5","textbook":"16_基础科技汉语教程听力课本","lesson":"58_动量守恒定律"},{"sentence":"相互之间有作用力的物体通常称为一个系统，系统中各个物体之间的相互作用力称为这个系统的内力，系统外部其他物体对系统的作用力称为外力。例如：两个小球在桌面上碰撞过程中的相互作用就是系统的内力；两个小球还受到外力，如重力和桌面的支持力，但这两者之间是相互平衡的，所以由两个小球组成的系统，所受到的外力的合力为零。","path":"06_物理专业汉语科技汉语系列_clean_v3/04_动量_第三节_动量守恒定律.txt","line":"2","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"04_动量_第三节_动量守恒定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:1a2251e5d35043f7","words":["上层","下层"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5922,"first":"上层","second":"下层"},{"line":7016,"first":"下层","second":"上层"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"夏季沙漠中烈日当头，沙土被晒得灼热，沙土附近的下层空气温度上升得很高，而上层空气的温度仍然很低，这样就形成了气温的反常分布。由于热胀冷缩，接近沙土的下层热空气密度小而上层冷空气的密度大，这样空气的折射率是下层小而上层大。当远处较高物体反射出来的光从上层较密空气进入下层较疏空气时被不断折射，其入射角逐渐增大，增大到等于一定角度时发生全反射，这时，人类是逆着反射光线看去，就会看到蜃景。","path":"30_中级汉语分类阅读科技篇II/36_地貌_虚无缥缈的海市蜃楼.txt","line":"11","textbook":"30_中级汉语分类阅读科技篇II","lesson":"36_地貌_虚无缥缈的海市蜃楼"},{"sentence":"在海洋和沙漠的特定环境下，上层空气和下层空气的密度由于温度的差异而变化明显，当光在密度不同的空气中前进时，也会不断地发生折射现象。这样，光就不走直线了，而是不断拐弯，形成一条抛物线，把远方低于海平面的物体像反射到半空中。人们往直线方向的远处望去，就看到在海面上出现一座城市了。","path":"27_新编科技汉语中级阅读教程/09_阅读1蓬莱仙境.txt","line":"4","textbook":"27_新编科技汉语中级阅读教程","lesson":"09_阅读1蓬莱仙境"},{"sentence":"蜃景不仅能在海上、沙滩中产生，柏油马路上偶尔也会看到。柏油马路因路面颜色深，夏天在灼热阳光下吸热能力强，同样会在路面上空形成上层的空气冷、密度大，而下层空气热、密度小的分布特征，所以也会形成蜃景。","path":"30_中级汉语分类阅读科技篇II/36_地貌_虚无缥缈的海市蜃楼.txt","line":"13","textbook":"30_中级汉语分类阅读科技篇II","lesson":"36_地貌_虚无缥缈的海市蜃楼"}],"evidenceUnit":"original_source_line"},{"id":"ANT:6b59ad01aececeea","words":["上方","下方"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5914,"first":"上方","second":"下方"},{"line":6956,"first":"下方","second":"上方"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"绿色食品标志图形由三部分构成，包括上方的太阳、下方的叶片和中心的蓓蕾，标志象征自然生成；颜色为绿色，象征着生命、农业、环保；图形为正圆形，意为保护。绿色食品标志文字中英文分别为“绿色食品”和“Green Food”。AA级绿色食品标志与文字均为绿色，底色为白色，A级绿色食品则标志与文字为白色，底色为绿色。","path":"27_新编科技汉语中级阅读教程/11_阅读3何谓“绿色食品”.txt","line":"5","textbook":"27_新编科技汉语中级阅读教程","lesson":"11_阅读3何谓“绿色食品”"},{"sentence":"飞机能飞上天除了靠发动机的动力以外，飞机的机翼是必不可少的。你是否注意过机翼的形状，这种形状对于飞机上天有什么作用呢？飞机机翼的上表面是个向上的弧形，机翼下表面是平的。飞机起飞前，要在跑道上快跑一段很长的距离，飞机向前快速前进，空气相对飞机向后运动。空气流到机翼前缘，就会分成上下两股气流，分别沿机翼上下表面流过，然后在机翼后缘重新汇合向后流去。机翼上表面比较凸出，流管较细，因此流速加快，压力降低；机翼下表面的气流受到阻挡，流管变粗，流速减慢，压力增大，于是上下表面出现了压力差。机翼下方的压力比上方大，这样便产生了升力，从而托起飞机，使飞机克服自身重力，飞上蓝天。","path":"15_基础科技汉语教程阅读课本下/31_01_飞机为什么能飞上天？.txt","line":"3","textbook":"15_基础科技汉语教程阅读课本下","lesson":"31_01_飞机为什么能飞上天？"},{"sentence":"在视线和水平线所成的角中，视线在水平线上方的是仰角，视线在水平线下方的是俯角。","path":"22_科技汉语听说教程/06_位置与方向.txt","line":"58","textbook":"22_科技汉语听说教程","lesson":"06_位置与方向"}],"evidenceUnit":"original_source_line"},{"id":"ANT:ff1d79bbbae295a3","words":["上面","下面"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5864,"first":"上面","second":"下面"},{"line":6900,"first":"下面","second":"上面"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"上式中，M 表示最上面一层的根数，N 表示最下面一层的根数，P 表示层数。","path":"12_基础科技汉语教程听说课本上/11_钢管总数的计算.txt","line":"12","textbook":"12_基础科技汉语教程听说课本上","lesson":"11_钢管总数的计算"},{"sentence":"苗族的吊脚楼一般都是建造在斜坡上，分成两层或者三层，最上面一层很矮，只用来存放食物不住人，楼下用来放杂物或者饲养牲口。在斜坡上建造吊脚楼，把地削成一个“厂”字形的土平台，土平台下面用长木柱作为支撑，按照土平台的高度取一段装上穿枋和横梁，与土平台平行。","path":"19_科技汉语/17_苗族吊脚楼建筑研究.txt","line":"12","textbook":"19_科技汉语","lesson":"17_苗族吊脚楼建筑研究"},{"sentence":"如果这堆粗细相同的钢管堆放成等腰梯形的形状，比如，最上面一层有sz根，下面每一层都比上面一层多sz根，最下面一层是sz根，那么，如何计算这堆钢管的总数呢？","path":"12_基础科技汉语教程听说课本上/11_钢管总数的计算.txt","line":"7","textbook":"12_基础科技汉语教程听说课本上","lesson":"11_钢管总数的计算"}],"evidenceUnit":"original_source_line"},{"id":"ANT:05e7881873c1f646","words":["上边","下边"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5924,"first":"上边","second":"下边"},{"line":7018,"first":"下边","second":"上边"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"大家知道，热空气比冷空气轻，所以热空气在冷空气的上边。根据这个道理，可以在房间的一边墙上开两个窗户：一个开在最上边，另一个开在最下边。这样做，从通风这一点看，要比开两个一样高的窗户好。不过窗户开得太高和太低，室内都很黑，所以一般都把窗户开在墙的中间。","path":"14_基础科技汉语阅读/03_第三课_出汗与散热_02_室内通风.txt","line":"6","textbook":"14_基础科技汉语阅读","lesson":"03_第三课_出汗与散热_02_室内通风"},{"sentence":"道理很简单。假如我们紧接着这一堆钢管，再放上同样数量的一堆，只是次序跟原来的相反，也就是最上边一层是sz根，最下边一层是sz根。这样，两堆合在一起，每一层的根数都相等，正好是原来一堆最下边一层的根数加上sz的和：sz根)","path":"12_基础科技汉语教程听说课本上/11_钢管总数的计算.txt","line":"5","textbook":"12_基础科技汉语教程听说课本上","lesson":"11_钢管总数的计算"},{"sentence":"假如我们紧接着这堆钢管再放上同样数量的一堆，只是次序跟原来的相反，也就是最上面一层是sz根，最下面一层是sz根，这样两堆合在一起，我们就会发现，每层的根数相等，正好是原来那堆最下边一层的根数加上最上边一层的根数的和。层数仍旧是sz层。这样我们就不难计算了。sz根加上sz根，乘以sz，就是两堆钢管的总数，再除以sz，就是一堆钢管的根数。","path":"16_基础科技汉语教程听力课本/11_堆放成等腰梯形的钢管总数.txt","line":"4","textbook":"16_基础科技汉语教程听力课本","lesson":"11_堆放成等腰梯形的钢管总数"}],"evidenceUnit":"original_source_line"},{"id":"ANT:dfa9bf99c0f990fa","words":["上限","下限"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5904,"first":"上限","second":"下限"},{"line":6886,"first":"下限","second":"上限"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"其实，早在两千多年前，阿基米德就用迭代算法和两侧数值逼近的概念，计算出了圆周率的近似值。阿基米德从单位圆出发，先用内接正六边形求出圆周率的下限，再用外切正六边形并借助勾股定理求出圆周率的上限。接着，他对内接正六边形和外切正六边形的边数分别加倍，将它们分别变成内接正十二边形和外切正十二边形，再借助勾股定理改进圆周率的下限和上限。他逐步对内接正多边形和外切正多边形的边数加倍，直到内接正九十六边形和外切正九十六边形为止。最后，阿基米德算出来，圆周率比一个数值大，比另一个数值小，圆周率的近似值为一个数值。阿基米德这个方法告诉我们，如果不能直接精确地决定一个数字，可以去找这个数字的下限以及上限。当下限和上限非常接近时，我们就可以相当准确地估算这个数字是多少了。仔细看看阿基米德的算法，他基本的观念是把圆周分成等分的圆弧，然后用内接九十六边形和外切九十六边形的边长作为圆弧长度的下限和上限。","path":"02_理工中文/01_第一章北京冬奥会中的几何美学_01_圆周率和圆的面积.txt","line":"8","textbook":"02_理工中文","lesson":"01_第一章北京冬奥会中的几何美学_01_圆周率和圆的面积"}],"evidenceUnit":"original_source_line"},{"id":"ANT:437660f0f51ea0ee","words":["上界","下界"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5870,"first":"上界","second":"下界"},{"line":6949,"first":"下界","second":"上界"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"第一，是有界还是无界。比如sin x、cos x是有界的，它上不超过sz，下不小于sz；x²有下界而无上界；tan x没有上界，也没有下界。还有这样的函数，它在每个区间上都是无界。","path":"18_科技汉语基础篇/02_函数及其图像_03_相关阅读.txt","line":"11","textbook":"18_科技汉语基础篇","lesson":"02_函数及其图像_03_相关阅读"}],"evidenceUnit":"original_source_line"},{"id":"ANT:c836ab101953b495","words":["上游","下游"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5900,"first":"上游","second":"下游"},{"line":6881,"first":"下游","second":"上游"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"此技术在应用时必须要有上、下游两个水库。在负荷低的时间，抽水储能的设备将下游水库的水抽到上游水库保存。在负荷最高时，抽水储能的设备利用存储在上游水库中的水发电。","path":"02_理工中文/09_第九章未来电网_02_储能技术.txt","line":"6","textbook":"02_理工中文","lesson":"09_第九章未来电网_02_储能技术"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f886264c0fb606be","words":["右边","左边"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7296,"first":"右边","second":"左边"},{"line":7559,"first":"左边","second":"右边"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"天平及砝码：粗略称量固体的质量。左边放固体药品，右边放砝码。","path":"03_化学专业汉语科技汉语系列_clean_v3/18_合成材料.txt","line":"71","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"18_合成材料"},{"sentence":"为了证实结论的正确，伽利略设计了一个理想实验，下面利用一个跟他的理想实验装置相似的实验，向大家介绍一下伽利略的实验。有两个斜面，用一个小球放到左边的斜面上，放手后小球从左边斜面上滚下后滚到右边的斜面上。在有摩擦力的情况下，到达右边斜面的高度比左边的释放高度要低。","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第一节_牛顿第一定律.txt","line":"7","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第一节_牛顿第一定律"},{"sentence":"伽利略所设计的实验是这样的：实验装置跟现在的一样，实验时若没有摩擦力，小球在这个理想实验中会怎样运动。把小球放到左边斜面的某一个高度，放手后，做加速运动，所以小球从斜面上滚下时，会越滚越快；到右边斜面下端时，开始做减速运动，小球会越滚越慢。在没有摩擦力的情况下，小球应达到左边的释放高度。改变右边斜面的倾角，使之变小，小球仍要达到同样的高度，就要在斜面上走更远的距离。当右边倾角为零时，小球将一直滚下去也永远达不到左边的释放高度，因此这个速度将保持不变。这个实验虽然是个理想实验，但却是符合科学道理的。法国科学家笛卡尔补充和完善了伽利略的论点，提出了惯性定律：如果没有其他原因，运动的物体将继续以同一速度沿着一条直线运动，既不会停下来，也不会偏离原来的方向。伽利略和笛卡尔对物体的运动做了准确的描述，但是没有指明加速、减速和匀速运动的原因是什么，以及这个原因与运动的关系是什么。而牛顿回答了这个问题。","path":"06_物理专业汉语科技汉语系列_clean_v3/03_牛顿定律_第一节_牛顿第一定律.txt","line":"8","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"03_牛顿定律_第一节_牛顿第一定律"}],"evidenceUnit":"original_source_line"},{"id":"ANT:08da802bfb924705","words":["前面","后面"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5146,"first":"前面","second":"后面"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"如果主链上有相同的取代基，将取代基合并起来，用“二、三”等数字表示，在用于表示取代基位置的阿拉伯数字之间要用“，”号隔开；如果主链上有几个不同的取代基，就把简单的写在前面，把复杂的写在后面。","path":"03_化学专业汉语科技汉语系列_clean_v3/15_烃.txt","line":"29","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"15_烃"},{"sentence":"望远镜里前后有两块玻璃镜片：前面一块接近于景物的凸形透镜或凹形反射镜叫物镜，直径大、焦距长；后面靠近眼睛的那块叫目镜，直径小、焦距短。远处景物反射过来的光线经过物镜聚焦在一点上，这就是焦点。焦点和物镜的距离就是焦距。","path":"13_基础科技汉语教程听说课本下/38_望远镜·电子显微镜.txt","line":"4","textbook":"13_基础科技汉语教程听说课本下","lesson":"38_望远镜·电子显微镜"},{"sentence":"汽车里的乘客，当汽车突然开动时，身体要向后面倾倒，这是因为汽车已经开始前进，而乘客由于惯性要保持静止状态的缘故。当汽车突然刹车时，身体要向前面倾倒，这是因为汽车已经停止，而乘客由于惯性要保持原来速度前进的缘故。总之，一切物体都具有惯性。惯性是物体的固有性质。","path":"13_基础科技汉语教程听说课本下/54_机械运动·牛顿第一定律·运动和力.txt","line":"23","textbook":"13_基础科技汉语教程听说课本下","lesson":"54_机械运动·牛顿第一定律·运动和力"}],"evidenceUnit":"original_source_line"},{"id":"ANT:213cd5837f52068a","words":["外面","里面"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4183,"first":"里面","second":"外面"},{"line":6449,"first":"外面","second":"里面"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"首先，可以通过金属条区分，医用口罩的颜色基本相同，一般金属条在上方并且向外面凸出的一面是外面，相反的一面则是里面；第二点，通过折痕来区分，折痕向上的一侧是里面，反之则是外面；第三点，通过线头区分，带线头的那一面是外面，反之，没有线头的那一面是反面；","path":"02_理工中文/13_第十三章公共卫生危机处理_04_大自然中有很多微生物。.txt","line":"12","textbook":"02_理工中文","lesson":"13_第十三章公共卫生危机处理_04_大自然中有很多微生物。"},{"sentence":"第四点，口罩的正反面颜色一般是不同的，外面那一层一般是浅蓝色或者深颜色，里面那一层一般是白色；最后，通过面料区分，根据光滑程度来看，口罩朝外的部分因为阻隔水，是比较光滑的，朝内的部分由比较透气的网状组织制作而成，是比较粗糙的。","path":"02_理工中文/13_第十三章公共卫生危机处理_04_大自然中有很多微生物。.txt","line":"13","textbook":"02_理工中文","lesson":"13_第十三章公共卫生危机处理_04_大自然中有很多微生物。"},{"sentence":"（sz）电镀：在某些金属表面镀上一层其他金属，外面的金属可以保护里面的金属不会被腐蚀。电镀时，阳极连接镀层金属，阴极是待镀金属。","path":"04_化学精讲精练/第十五章 原电池与电解池.txt","line":"17","textbook":"04_化学精讲精练","lesson":"第十五章 原电池与电解池"}],"evidenceUnit":"original_source_line"},{"id":"ANT:1857437ae96af5a8","words":["以内","以外"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7317,"first":"以内","second":"以外"},{"line":12078,"first":"以外","second":"以内"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"细胞质是指细胞膜以内、细胞核以外的黏稠胶状物质。活细胞的细胞质一般处于流动状态。细胞质中分布着许多与生命活动至关重要的微小结构，比如某些植物细胞具有的叶绿体以及植物和动物细胞内都具有的线粒体等。叶绿体中含有叶绿素，叶绿素可将光能进行转化，并把转化后的能量储存在所制造的有机物里；线粒体则能将细胞中的一些有机物经过复杂的过程转变成二氧化碳和水，并将有机物里的能量释放出来。此外，在成熟植物细胞的细胞质中还存在着液泡，液泡内充满细胞液。我们吃水果时尝到的酸甜味道，就和细胞液的成分有关。","path":"26_科技汉语中级教程/15_第十五单元 走近细胞_第一节 细胞的基本结构.txt","line":"15","textbook":"26_科技汉语中级教程","lesson":"15_第十五单元 走近细胞_第一节 细胞的基本结构"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0400059e741f1d0c","words":["局部","整体"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7960,"first":"整体","second":"局部"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"首先，我们来了解一些分形的科普小知识。关于分形，首先涉及的是其自相似性，所谓自相似性是指局部是整体成比例缩小的性质。通俗一点说，就是当用不同倍数的照相机拍照，无论放大倍数如何改变，看到的照片都是相似的。由此，你能想象科赫雪花曲线的自相似性吗？","path":"02_理工中文/01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密.txt","line":"3","textbook":"02_理工中文","lesson":"01_第一章北京冬奥会中的几何美学_03_雪花图形里的秘密"},{"sentence":"（三）宁可局部小弯，但求整体大直。（四）轮廓、转折等处可加粗强调。","path":"28_新编科技汉语高级阅读教程/12_第十二单元 建筑漫谈_05_科技写作及规范.txt","line":"5","textbook":"28_新编科技汉语高级阅读教程","lesson":"12_第十二单元 建筑漫谈_05_科技写作及规范"}],"evidenceUnit":"original_source_line"},{"id":"ANT:b595dda15d6b802d","words":["至多","至少"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7823,"first":"至少","second":"至多"},{"line":7829,"first":"至多","second":"至少"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"正面词语：=，>，是，都是，至多有一个，至少有一个，任意的，所有的","path":"09_数学专业汉语科技汉语系列_clean_v3/02_第二单元 简单的逻辑.txt","line":"104","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"02_第二单元 简单的逻辑"}],"evidenceUnit":"original_source_line"},{"id":"ANT:9d92a239a556dd72","words":["主要","次要"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1274,"first":"次要","second":"主要"},{"line":7768,"first":"主要","second":"次要"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"四合院的庭院与组群布局，大多采用均衡对称的方式，沿着纵轴线和横轴线进行设计。首先在纵轴线上安置主要建筑，并在院子左右两侧对称修建两座形体较小的建筑，然后在主要建筑的对面建一座次要建筑，构成正方形或长方形的庭院。对称式平面与封闭式外观是四合院的两个主要特点，这种布局适合中国古代社会的宗法与礼教制度，便于安排家庭成员的住所，易形成安静舒适的生活环境。","path":"19_科技汉语/14_四合院与四合院文化.txt","line":"10","textbook":"19_科技汉语","lesson":"14_四合院与四合院文化"},{"sentence":"包内右侧为家中主要成员座位和宿处，左侧一般为次要成员座位和宿处（蒙古族住房也以西为大，长者居右)。蒙古包的中间设有供饮饮和取暖的火炉，烟筒从包顶的天窗出去（古时没有火炉和烟筒，一般都是在帐幕中间生火，烟从天窗出去)。现代卧榻有的铺设木床，有的设有矮床。","path":"19_科技汉语/15_蒙古包.txt","line":"11","textbook":"19_科技汉语","lesson":"15_蒙古包"}],"evidenceUnit":"original_source_line"},{"id":"ANT:ba2d598c92b6b2ad","words":["危险","安全"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":677,"first":"安全","second":"危险"},{"line":6373,"first":"危险","second":"安全"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"飞鸟对昆虫的捕食和食肉动物一样，也起到保护草原的作用。而飞禽走兽的粪便则成为上好肥料，促使各种植物的生长。我国北方的呼伦贝尔大草原，曾经野狼成群。为了保护人畜的安全，当地牧民曾经组织过大规模的猎捕野狼的活动，使野狼的数量迅速减少。野狼不见了，畜牧业空前发展。在牛羊种群数量不断增加的同时，野兔以惊人的速度发展起来。野兔和牛羊争食牧草，草原难以承载，导致草场急剧退化，使草原面临沙化的危险。","path":"29_中级汉语分类阅读科技篇I/12_生态_话说食物链.txt","line":"5","textbook":"29_中级汉语分类阅读科技篇I","lesson":"12_生态_话说食物链"},{"sentence":"根据欧姆定律，导体中的电流与导体两端的电压成正比。人体也是导体，电压越高，通过的电流越大，对人身就越有危险。只有不高于sz的电压才是安全的。家庭电路的电压是sz，远远超出了安全电压，一旦发生触电，很可能有生命危险。","path":"20_科技汉语读写教程/18_条件限制.txt","line":"18","textbook":"20_科技汉语读写教程","lesson":"18_条件限制"},{"sentence":"家庭的引导和监督是内容安全防护不可或缺的一环。作为网络原住民的sz后一代几乎可以无师自通地学会上网，但他们缺少的是必要的网络风险识别能力。很多父母经常用一部手机来让“熊孩子”们安静下来，但是也很容易让他们暴露于网络空间的危险之中。因此，即使是玩手机，父母的陪伴和引导也同样不可缺席。正在审议中的未成年人保护法特别提出了针对未成年人的网络保护，专家建议在第六十四条中增加完善针对未成年人的网络信息产品和服务的准入制度，加强对网络信息产品和服务的监管。我们期待，在顶层设计之下，能够切实多方合力，营造健康、文明、有序的网络环境，抵御不良侵害，为未成年人提供更多的成长力量。","path":"19_科技汉语/20_如何守护孩子的信息安全.txt","line":"14","textbook":"19_科技汉语","lesson":"20_如何守护孩子的信息安全"}],"evidenceUnit":"original_source_line"},{"id":"ANT:997d650b1342ae8e","words":["保护","破坏"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1113,"first":"保护","second":"破坏"},{"line":4723,"first":"破坏","second":"保护"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"科学家普遍认为，电冰箱、空调机中使用的氟利昂是罪魁祸首之一。氟里昂变成气体上升到空中，破坏臭氧的结构，使臭氧浓度减少。此外，还有含氟里昂的洗涤剂等也破坏臭氧分子的结构。现在，各国为了保护臭氧层，都在积极生产和使用无氟冰箱。","path":"15_基础科技汉语教程阅读课本下/37_01_臭氧层与臭氧空洞.txt","line":"6","textbook":"15_基础科技汉语教程阅读课本下","lesson":"37_01_臭氧层与臭氧空洞"},{"sentence":"臭氧层与人类以及地球上的生物关系如此密切，我们应该好好儿保护它。然而，随着工业化的发展，人为造成的对臭氧层的破坏十分严重，这其中电冰箱、空调机、汽车的大量使用所造成的破坏更加突出。因此，要减少使用或者不用一切对臭氧层有破坏作用的物质。研究发现，破坏臭氧层的主要物质是氟利昂。近年来，世界各国都在进行技术开发，推广使用氟里昂的替代物和无氟产品。无氟冰箱、无氟空调机等已经走进了百姓家。","path":"13_基础科技汉语教程听说课本下/37_保护臭氧层.txt","line":"5","textbook":"13_基础科技汉语教程听说课本下","lesson":"37_保护臭氧层"},{"sentence":"大气中的臭氧层能吸收太阳的大部分紫外线，使地球上的生物免遭伤害。但氟氯烃，商品名为氟利昂，等气体能破坏臭氧层。因此，应减少并逐步停止氟氯烃的生产和使用，以保护臭氧层。","path":"20_科技汉语读写教程/18_条件限制.txt","line":"23","textbook":"20_科技汉语读写教程","lesson":"18_条件限制"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f05dbfa8ba0eb9fb","words":["破坏","维护"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4723,"first":"破坏","second":"维护"},{"line":12346,"first":"维护","second":"破坏"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"生态平衡是大自然经过了很长时间才建立起来的动态平衡。一旦受到破坏，有些平衡就无法重建了，带来的恶果可能是靠人的努力而无法弥补的。因此人类要尊重生态平衡，帮助维护这个平衡，绝不要轻易去干预大自然，引起这个平衡被打破。","path":"29_中级汉语分类阅读科技篇I/11_生态_漫话生态平衡.txt","line":"7","textbook":"29_中级汉语分类阅读科技篇I","lesson":"11_生态_漫话生态平衡"},{"sentence":"绝大多数的昆虫，在冬季到来时不是“虫”或“幼虫”，而是以“蛹”或“卵”的形式进行冬眠。在冬天，昆虫要保持活动，不被冻僵是至关重要的。活的组织一旦被冻结，膨胀的水晶体势必使细胞膜受到破坏，造成致命的创伤。当细胞里液体不足，不能保持维护生命所必需的酶活性时，即使没有完全被冻结，也会造成死亡。那么，昆虫是怎样解决这一难题的呢？它们主要是靠降低体内液体的冰点，从而提高抗寒能力，办法就是产生大量的“防冻液”。在实验室中，科学家把青蛙冷冻sz天再慢慢解冻，它们依然活着，体液中含有防冻剂中常用的丙三醇。但在温暖的季节里，它们体内却找不到这一物质。","path":"30_中级汉语分类阅读科技篇II/03_动物_动物冬眠之谜.txt","line":"13","textbook":"30_中级汉语分类阅读科技篇II","lesson":"03_动物_动物冬眠之谜"}],"evidenceUnit":"original_source_line"},{"id":"ANT:2a8b876b05938f2a","words":["出现","消失"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6752,"first":"消失","second":"出现"},{"line":13638,"first":"出现","second":"消失"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"我国量子态隐形传输获突破，去年实现世界最远距离传输。 存放着机密文件的保险箱被放入一个特殊装置之后，可以突然消失，并在同一瞬间出现在相距遥远的另一个特定装置中，被人方便地取出。记者从中国科学技术大学获悉，目前，由中科大和清华大学组成的联合小组在量子态隐形传输技术上取得的新突破，可能使这种以往只能出现在科幻电影中的“超时空穿越”神奇场景变为现实。","path":"24_科技汉语阅读教程/47_月光宝盒不是神话时空穿越或成现实.txt","line":"3","textbook":"24_科技汉语阅读教程","lesson":"47_月光宝盒不是神话时空穿越或成现实"},{"sentence":"宇宙飞船和人造地球卫星绕地球运转时所需要的向心力，完全是由地球的吸引力提供的,地球的吸引力等于向心力。这时重力为零，所以出现了失重现象。但是重力并没有消失，而是表现为向心力了。“失重”是指物体失去重量，而不是失去重力，重力只是有了不同的表现。","path":"14_基础科技汉语阅读/18_第十八课_人造地球卫星的速度_02_失重.txt","line":"10","textbook":"14_基础科技汉语阅读","lesson":"18_第十八课_人造地球卫星的速度_02_失重"},{"sentence":"“在经典状态下，一个个独立的光子自携带信息，通过发送和接收装置进行信息传递。但是在量子状态下，两个纠缠的光子互为一组，互相关联，并且可以在一个地方神秘消失，不需要任何载体的携带，又在另一个地方瞬间神秘出现。量子态隐形传输利用的就是量子的这种特性，我们首先把一对携带着信息的纠缠的光子进行拆分，将其中一个光子发送到特定位置，这时，两地之间只需要知道其中一个光子的即时状态，就能准确推测另外一个光子的状态，从而实现类似‘超时空穿越’的通信方式。”彭承志说。","path":"24_科技汉语阅读教程/47_月光宝盒不是神话时空穿越或成现实.txt","line":"5","textbook":"24_科技汉语阅读教程","lesson":"47_月光宝盒不是神话时空穿越或成现实"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3c2f751c61144928","words":["开始","结束"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3372,"first":"结束","second":"开始"},{"line":14013,"first":"开始","second":"结束"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"来龙去脉：比喻事情的开始结束、前因后果。","path":"30_中级汉语分类阅读科技篇II/13_气象_天气预报的来历.txt","line":"16","textbook":"30_中级汉语分类阅读科技篇II","lesson":"13_气象_天气预报的来历"},{"sentence":"元素周期表有七个横行，称为七个周期。具有相同的电子层数的元素按照原子序数递增的顺序排列的一个横行称为一个周期。周期的序数就是该周期元素具有的电子层数，比如钙原子核外电子层数为四层，那么钙在第四周期。其中，第一、二、三周期称为短周期，第四、五、六周期称为长周期，第七周期称为不完全周期。除第一周期只包括氢和氦、第七周期尚未填满外，每一周期的元素都是从最外层电子数为一的碱金属开始，逐渐过渡到最外层电子数为七的卤素，最后以最外层电子数为八的稀有气体元素结束。","path":"03_化学专业汉语科技汉语系列_clean_v3/03_基本概念和基本理论.txt","line":"126","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"03_基本概念和基本理论"},{"sentence":"通过注销功能可以使用户在不重启计算机的情况下登录系统。单击“开始”按钮，选择“注销”对话框，可以看到有“切换用户”和“注销”两个选项。“切换用户”是指在不关闭当前用户的情况下，由另一用户登录进入 Windows，这时当前运行的程序不被结束，系统中同时存在多个用户。“注销”是指关闭当前用户，由另一用户登录进入 Windows，系统中只有一个用户。","path":"26_科技汉语中级教程/14_第十四单元 Windows XP 操作系统_第一节 Windows XP基础.txt","line":"30","textbook":"26_科技汉语中级教程","lesson":"14_第十四单元 Windows XP 操作系统_第一节 Windows XP基础"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8f06ef327b1a13e8","words":["开始","终止"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7851,"first":"终止","second":"开始"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"平面内一条射线绕着它的端点从一个位置旋转到另一个位置所形成的图形叫做角。射线的端点叫做角的顶点，旋转开始时的射线叫做角的始边，终止时的射线叫做角的终边。","path":"09_数学专业汉语科技汉语系列_clean_v3/04_第四单元  三角函数和反函数.txt","line":"9","textbook":"09_数学专业汉语科技汉语系列_clean_v3","lesson":"04_第四单元  三角函数和反函数"}],"evidenceUnit":"original_source_line"},{"id":"ANT:bf289e2d35fd3f61","words":["关闭","打开"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2432,"first":"关闭","second":"打开"},{"line":12820,"first":"打开","second":"关闭"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"菜单栏位于主窗口标题栏的下面，是系统命令的汇总。每个菜单的标题表明该菜单上命令的用途，如“文件”、“编辑”、“帮助”等。“文件”菜单通常包含诸如“新建”、“打开”、“关闭”、“保存”、“属性”等菜单选项。","path":"26_科技汉语中级教程/14_第十四单元 Windows XP 操作系统_第二节 Windows XP的基本概念.txt","line":"25","textbook":"26_科技汉语中级教程","lesson":"14_第十四单元 Windows XP 操作系统_第二节 Windows XP的基本概念"},{"sentence":"(sz)双击窗口的控制图标；或者单击窗口的控制图标打开控制菜单，然后选择“关闭”命令。","path":"26_科技汉语中级教程/14_第十四单元 Windows XP 操作系统_第三节 Windows XP的基本操作.txt","line":"33","textbook":"26_科技汉语中级教程","lesson":"14_第十四单元 Windows XP 操作系统_第三节 Windows XP的基本操作"}],"evidenceUnit":"original_source_line"},{"id":"ANT:4f8d194e6fd9b2be","words":["关闭","开启"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2432,"first":"关闭","second":"开启"},{"line":3885,"first":"开启","second":"关闭"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"散热、冷却器件实时状态下实施系统自适应当前状态的控制。根据电池包状态，系统进行自适应状态的控制，当电池包温度大于等于一定温度时，系统自动开启散热功能进行冷却，当温度小于等于一定温度时，散热系统关闭，保证了高温情况下的散热良好，让电池包在最优的条件下工作。控制状态下自动识别和自动切换电池包处于低温状态时也会自动识别，当小于等于一定温度时，电池包识别后自动开启加热功能，当加热温度达到一定温度后，停止加热，自动切换为充电模式，系统控制电池包在不同温度下切换为最优模式进行工作。","path":"19_科技汉语/06_纯电动车用动力电池热管理系统设计.txt","line":"8","textbook":"19_科技汉语","lesson":"06_纯电动车用动力电池热管理系统设计"}],"evidenceUnit":"original_source_line"},{"id":"ANT:109cf81543d56885","words":["张开","闭合"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":948,"first":"闭合","second":"张开"},{"line":8000,"first":"张开","second":"闭合"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"取一对用绝缘支柱支持的金属导体A和B，使它们彼此接触。起初它们不带电，则在它们下部的金属片是闭合的。现在把带正电荷的球C移近导体A，可以看到A、B上的金属片都张开了，表示A、B都带上了电荷，如图。实验表明：导体A上带负电荷，与C上的电荷异号；导体B上带正电荷，与C上的电荷同号。如果先把A和B分开，然后移去C，可以看到A和B仍带有电荷。如果再让A和B接触，它们就不再带电。这说明了A和B分开后所带的异种电荷是等量的，重新接触后等量异种电荷发生中和。把电荷移近不带电的导体，可以使导体带电，这种现象叫作静电感应。利用静电感应使物体带电，叫作感应起电。","path":"06_物理专业汉语科技汉语系列_clean_v3/06_电场_第一节_电荷与库伦定律.txt","line":"11","textbook":"06_物理专业汉语科技汉语系列_clean_v3","lesson":"06_电场_第一节_电荷与库伦定律"},{"sentence":"科学家从蝴蝶身上得到了启示。他们发现蝴蝶的鳞片具有调节体温的作用。当太阳直射时，鳞片会自动张开，以减小太阳光的辐射角度，从而可大大减少吸收的太阳光的热量；当外界温度下降时，鳞片又会自动闭合，紧贴体表，使太阳光直射到身上，更多地吸收太阳光的热量。","path":"16_基础科技汉语教程听力课本/25_蝴蝶与航天技术.txt","line":"6","textbook":"16_基础科技汉语教程听力课本","lesson":"25_蝴蝶与航天技术"}],"evidenceUnit":"original_source_line"},{"id":"ANT:6c3bcee62a7b9113","words":["点燃","熄灭"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6930,"first":"熄灭","second":"点燃"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"对一支蜡烛在点燃前、燃烧时和熄灭后的三个阶段进行观察，并将观察到的現象在下表中作详尽的、客观的描述和记录。","path":"20_科技汉语读写教程/20_问题解读（一）.txt","line":"39","textbook":"20_科技汉语读写教程","lesson":"20_问题解读（一）"},{"sentence":"实验：把棉手帕放入用酒精与水以配成的溶液里浸透，然后轻挤，用小钳子分别夹住手帕两角，放到火上点燃，等火焰减小时迅速摇动手帕，使火焰熄灭，这时会发现手帕依旧完好如初。","path":"24_科技汉语阅读教程/08_趣味实验（一）.txt","line":"6","textbook":"24_科技汉语阅读教程","lesson":"08_趣味实验（一）"}],"evidenceUnit":"original_source_line"},{"id":"ANT:72e18c5b57b810cb","words":["分散","集中"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2197,"first":"分散","second":"集中"},{"line":3691,"first":"集中","second":"分散"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"光线既然不能完美汇聚，也就不可能产生清楚的成像。当光圈变大（光圈F值小）的时候，透镜接收光的圆面很大，光线的汇聚处就会非常分散，造成成像不清晰的现象。当光圈缩小的时候，透镜接收光的圆面很小，光线经过透镜以后，汇聚处相对来说更集中一些，这样成像也就更加清晰了。但光圈如果太小，接收到的光太少，也会影响成像的清晰度。","path":"02_理工中文/08_第八章机器视觉_02_相机镜头光学中的疑难问题.txt","line":"14","textbook":"02_理工中文","lesson":"08_第八章机器视觉_02_相机镜头光学中的疑难问题"}],"evidenceUnit":"original_source_line"},{"id":"ANT:b80c92c41abfa875","words":["分散","聚集"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2197,"first":"分散","second":"聚集"},{"line":3187,"first":"聚集","second":"分散"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在加入洗涤剂的试管中，情况则不同。虽然植物油并没有溶解在水中，但形成的乳浊液却能够稳定地存在，液体不再分成两层。这是为什么呢？原来洗涤剂有乳化的功能，它能使植物油分散成无数细小的液滴，而不聚集成大的油珠。这些细小的液滴能随着水流走，因此试管的内壁很干净。","path":"26_科技汉语中级教程/11_第十一单元 溶液_第一节 溶液的基本概念.txt","line":"17","textbook":"26_科技汉语中级教程","lesson":"11_第十一单元 溶液_第一节 溶液的基本概念"}],"evidenceUnit":"original_source_line"},{"id":"ANT:b923717896710e87","words":["远离","靠近"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7074,"first":"远离","second":"靠近"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"“猫眼”是一种防盗门镜，由凹透镜和凸透镜组成。使用过“猫眼”的人都知道，从室内通过门镜向外看时，门外的景物都缩小了，眼睛能看到的视角范围很大。而且眼睛越靠近“猫眼”，观察景物的效果越好，可以看见比景物略小的正立虚像。这样一来，门外的人、发生的事，都能看得很清楚。而人在室外向屋里看时，无论眼睛靠近“猫眼”还是远离“猫眼”，都无法看清楚室内的景物。","path":"16_基础科技汉语教程听力课本/38_房门上的“猫眼”.txt","line":"3","textbook":"16_基础科技汉语教程听力课本","lesson":"38_房门上的“猫眼”"}],"evidenceUnit":"original_source_line"},{"id":"ANT:4371d1ef3a986da2","words":["离开","靠近"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4154,"first":"离开","second":"靠近"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"靠近均数分布的频数最多，离开均数越远，分布的数据越少，左右两侧基本对称。数据中间密集、两侧逐渐减少的基本对称的分布，称为正态分布。","path":"28_新编科技汉语高级阅读教程/07_第七单元 概率_01_课文.txt","line":"13","textbook":"28_新编科技汉语高级阅读教程","lesson":"07_第七单元 概率_01_课文"}],"evidenceUnit":"original_source_line"},{"id":"ANT:6f8801b62395f97b","words":["缓慢","迅速"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2858,"first":"缓慢","second":"迅速"},{"line":6481,"first":"迅速","second":"缓慢"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"栖息在草木茂盛的溪流边的漏斗网蛛，对于落网猎物的反应非常缓慢。而栖息在相邻干荒漠草原的漏斗网蛛，只要猎物一落网就会迅速跑到网上。这些同种蜘蛛在出击速度上的差异被认为是由于环境的差异。例如：栖息在溪流边的蜘蛛与栖息在荒漠草原的蜘蛛相比，猎物较为丰富，很少有饥饿感。","path":"24_科技汉语阅读教程/25_两个漏斗网蛛种群成员的行为差异.txt","line":"2","textbook":"24_科技汉语阅读教程","lesson":"25_两个漏斗网蛛种群成员的行为差异"},{"sentence":"植物是怎样变成煤炭的呢？由于石炭纪的植物种类繁多，生长迅速，它们死后即便有一部分很快腐烂，但仍有许多枝干倒伏后避免了风化作用和细菌、微生物的破坏。石炭纪的森林，不少是被水浸泡着的沼泽地。死亡后的植物枝干很快会下沉到稀泥中，那里实际上是一种封闭的还原环境。在这种环境中，植物枝干避免了外界的破坏，并在压实作用和其他作用下缓慢地演变成泥炭。年复一年，由植物形成的很多泥炭在地层中得到保存，再经历了成煤作用后，这些泥炭成为初级的煤炭——褐煤。褐煤是一种劣质煤，继续经过长时间的压实后，它才能形成真正意义上的煤——烟煤。褐煤转化成烟煤要付出巨大的“代价”。据地质学家推算，sz米厚的烟煤是由sz米厚的褐煤压缩而成的。","path":"30_中级汉语分类阅读科技篇II/40_地质_煤炭从哪里来？.txt","line":"11","textbook":"30_中级汉语分类阅读科技篇II","lesson":"40_地质_煤炭从哪里来？"}],"evidenceUnit":"original_source_line"},{"id":"ANT:98a2ff399ea614ee","words":["连续","间断"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3586,"first":"间断","second":"连续"},{"line":4080,"first":"连续","second":"间断"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"连锁：一环扣一环，像锁链似的，形容连续不间断。","path":"29_中级汉语分类阅读科技篇I/11_生态_漫话生态平衡.txt","line":"9","textbook":"29_中级汉语分类阅读科技篇I","lesson":"11_生态_漫话生态平衡"}],"evidenceUnit":"original_source_line"},{"id":"ANT:0088b6f8c68a88f9","words":["人造","天然"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5313,"first":"人造","second":"天然"},{"line":6154,"first":"天然","second":"人造"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"现在我们把磁铁吸引铁等物质的性质叫做磁性。除了天然磁铁以外，还有一种人造磁铁。人造磁铁的磁性比天然磁铁的磁性强得多。由于磁铁有吸引铁的性质，所以它的用途很多。","path":"14_基础科技汉语阅读/16_第十六课_摩擦与热、电、磁_02_阿房宫的大门.txt","line":"6","textbook":"14_基础科技汉语阅读","lesson":"16_第十六课_摩擦与热、电、磁_02_阿房宫的大门"},{"sentence":"棉花、羊毛、木材和草类的纤维都是天然纤维。用木材、草类的纤维经化学加工制成的粘胶纤维属于人造纤维；利用石油、天然气、煤和农副产品作原料制成单体，单体进一步聚合可以得到合成纤维。合成纤维和人造纤维统称化学纤维。","path":"03_化学专业汉语科技汉语系列_clean_v3/18_合成材料.txt","line":"39","textbook":"03_化学专业汉语科技汉语系列_clean_v3","lesson":"18_合成材料"}],"evidenceUnit":"original_source_line"},{"id":"ANT:fc49e252e6a7f6cd","words":["人工","天然"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6154,"first":"天然","second":"人工"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"中国园林按园林基址来可分为两类。第一类是人工山水园，在城镇的建筑环境里面创造模拟天然野趣的小环境，像是点点绿洲，故也称之为“城市山林”。第二类是天然山水园，兴造天然山水园如果选址合适，则能以少量的花费而获得远胜于人工山水园的天然风景之真趣。如果按建园者身份来分可分为三类。第一类是皇家园林，专供帝王休息享乐的园林。其特点是规模宏大，真山真水较多。第二类是私家园林，是供皇家的宗室、王公官吏、富商等休闲的园林。其特点是规模较小，所以常用假山假水，建筑小巧玲珑，表现其素净的色彩。第三类是寺观园林，佛寺和道观的附属园林，也包括寺观内部庭院和外围地段的园林化环境。","path":"19_科技汉语/16_中国古典园林的建筑艺术.txt","line":"11","textbook":"19_科技汉语","lesson":"16_中国古典园林的建筑艺术"},{"sentence":"人工湿地净化水质技术实际上是科学家受天然湿地净水功能的启发而发明的一项技术。在天然湿地中，丰富的野生植被及大量的生物对水质起到良好的净化作用，同时还能调节水分和气候，被人们称为“地球之肾”。在我国青藏高原、黑龙江等地有多种形式的自然湿地，种类繁多的动植物组成了一个良性循环的生态系统。","path":"17_汉语科技文选读/17.1_人工湿地.txt","line":"2","textbook":"17_汉语科技文选读","lesson":"17.1_人工湿地"},{"sentence":"sz年，中国科学家提出人工合成胰岛素的设想。当时国际上最高的科研水平，也只能合成由sz个氨基酸组成的多肽。胰岛素虽然是相对分子质量较小的蛋白质，但是也由sz种、sz个氨基酸、两条肽链组成。这项艰巨的任务由北京和上海两地的科研小组共同承担。经过集体研究，科研人员决定先把天然胰岛素的两条链拆开，摸索将两条链合在一起的方法；然后再分别合成两条链；最后将两条人工链合在一起。经过sz年零sz个月的不懈努力，中国科学家终于在sz年完成了结晶牛胰岛素的全部合成，更令人振奋的是，合成的胰岛素具有与天然胰岛素一样的生物活性！","path":"18_科技汉语基础篇/10_细胞_03_相关阅读.txt","line":"11","textbook":"18_科技汉语基础篇","lesson":"10_细胞_03_相关阅读"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f415bd8728862e8d","words":["低等","高等"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1872,"first":"低等","second":"高等"},{"line":2635,"first":"高等","second":"低等"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在神奇的化石世界中，人们首先注意到的往往是各种动物化石，而对植物化石认识较少。实际上，植物比动物出现得更早，植物界自形成以来，历经亿万年的变迁，它们的演化方式与动物界相似，也经历了从水生发展到陆生，从低等进化到高等的过程。在地球发展历史的每一阶段都有植物参与，很难想象，地球上没有植物将会是什么样子，人类失去植物将会怎样生活。","path":"30_中级汉语分类阅读科技篇II/40_地质_煤炭从哪里来？.txt","line":"3","textbook":"30_中级汉语分类阅读科技篇II","lesson":"40_地质_煤炭从哪里来？"}],"evidenceUnit":"original_source_line"},{"id":"ANT:8dffc4b1f93d806b","words":["低级","高级"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":2660,"first":"高级","second":"低级"},{"line":14627,"first":"低级","second":"高级"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"达尔文的生物进化理论认为：生物最初是从非生物发展而来的，现代生存的各种生物有着共同的祖先，在漫长的进化过程中通过变异、遗传和自然选择，生物由低级到高级，从简单到复杂，种类由少到多。达尔文指出：生物进化的主导力量是自然选择，那些发生细微不定变异的生物个体，如果适合了当时外界环境条件就可以生存下来，并通过累积的选择作用，逐渐使这种变异发展成为新的物种；如果不适合，就不能生存下来或不能使之后代。","path":"30_中级汉语分类阅读科技篇II/18_生命_生命从何而来.txt","line":"11","textbook":"30_中级汉语分类阅读科技篇II","lesson":"18_生命_生命从何而来"}],"evidenceUnit":"original_source_line"},{"id":"ANT:fc9dc11ef82a57b5","words":["雄性","雌性"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1271,"first":"雌性","second":"雄性"},{"line":6513,"first":"雄性","second":"雌性"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"大熊猫喜独居，每个熊猫有各自的活动领域，这与小熊猫很相似。至于食物，大熊猫也主食竹子，每座大山一般有sz多种竹子分布，大熊猫只觅食其中的两三种。有时大熊猫会捕食竹林中的竹鼠。大熊猫看似行动迟缓，实则身手灵活，善于爬树，遇到危险时大熊猫奔跑速度很快。大熊猫常在大树洞里生育，一胎产一仔，有时产两仔。大熊猫幼仔约sz克重，仅为母兽体重重的sz。幼仔刚出生时是粉红色，与成年熊猫形态差别很大。雌性大熊猫sz岁时性成熟，雄性sz岁时性成熟，大熊猫的发情交配与栖息地的生态环境关系密切。大熊猫一般每年sz月进入繁殖期，成年熊猫的发情期很短，只有短短的几天时间，雄性与雌性交配后即分开，雌性单独哺育幼熊猫。在人工饲养条件下，大熊猫的寿命可达sz岁。","path":"17_汉语科技文选读/04_生物世界_第4课.txt","line":"14","textbook":"17_汉语科技文选读","lesson":"04_生物世界_第4课"}],"evidenceUnit":"original_source_line"},{"id":"ANT:3358036a712525cf","words":["同性","异性"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":6105,"first":"同性","second":"异性"},{"line":7341,"first":"异性","second":"同性"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"磁悬浮列车由于车身与轨道不接触，不但运行速度很快，而且运行平稳、安全、舒适、无噪音，有利于环境保护。它的基本原理并不深奥，就是利用磁铁“同性相斥，异性相吸”的性质，克服地心引力，使列车完全脱离轨道而悬浮起来行驶。","path":"13_基础科技汉语教程听说课本下/45_磁悬浮列车.txt","line":"3","textbook":"13_基础科技汉语教程听说课本下","lesson":"45_磁悬浮列车"},{"sentence":"磁浮列车的基本原理并不复杂。地球磁场、电磁转换、磁极同性相斥、异性相吸，等等，都已出现在中学生的物理课本之中。人们甚至可以从“磁浮”联想到黄帝时期传说中的司南、指南针和后来的磁石散之类。但是，怎样把这些原理以极精密的方法加以组合，促使重达数十吨的车厢离地浮起，并且把时速为千米以上的超高速降至时速为“零”，平稳地停靠在目的地，就是一种尖端的高科技了。","path":"17_汉语科技文选读/15_现代技术应用_第15课.txt","line":"2","textbook":"17_汉语科技文选读","lesson":"15_现代技术应用_第15课"}],"evidenceUnit":"original_source_line"},{"id":"ANT:06adef6b4c5135a7","words":["主动","被动"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":1039,"first":"被动","second":"主动"},{"line":7781,"first":"主动","second":"被动"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"铯原子钟的长期稳定性较好，可以几天甚至十几天不对误差进行修正。铷原子钟在短时间内的精度要好于铯原子钟，但是时间稍长就要对误差进行修正。而氢原子钟则具备这两者共同的优点，但是设计相对复杂，应用难度比较高。氢原子钟分为主动和被动两种类型。主动型稳定度指标最优，但体积比较大，一般用于地面投射。被动型的体积小、重量轻、功耗低，稳定度指标仅次于主动型，多用于地面移动平台和卫星。早期GPS曾经考虑过使用氢原子钟，但后来因为样机模型未能通过地面测试而取消，转而采用了铯原子钟和铷原子钟结合的方式。欧洲的伽利略系统在立项之初的一个目标就是要超越GPS的精度。因此，伽利略系统的导航卫星上配备了铷原子钟和氢原子钟。","path":"02_理工中文/11_第十一章星载原子钟_02_卫星导航原子钟的类型.txt","line":"4","textbook":"02_理工中文","lesson":"11_第十一章星载原子钟_02_卫星导航原子钟的类型"}],"evidenceUnit":"original_source_line"},{"id":"ANT:7bf7e830288e9f79","words":["优点","缺点"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7230,"first":"优点","second":"缺点"},{"line":12103,"first":"缺点","second":"优点"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"在全球能源紧张、环境污染严重的情况下，新能源发电技术对人类发展有着重要意义。虽然新能源发电拥有许多优点，但其缺点也是不能忽视的。风、光等资源存在的缺点将导致实时的发电功率和电能需求不一致，影响电网的安全稳定运行并引起大量风能、光能浪费现象的发生。据统计，截至sz年sz月底，中国国内风能的平均浪费率为sz，光能的平均浪费率为sz。虽然目前新能源技术在发展上还存在一些问题，但它的光明前景是值得肯定的，相信新能源发电技术在不远的将来会成为世界各国发电方式的主流。","path":"02_理工中文/09_第九章未来电网_01_新能源发电.txt","line":"22","textbook":"02_理工中文","lesson":"09_第九章未来电网_01_新能源发电"}],"evidenceUnit":"original_source_line"},{"id":"ANT:2f48626f8f6613d3","words":["优势","劣势"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":4009,"first":"劣势","second":"优势"},{"line":7159,"first":"优势","second":"劣势"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"人体外部形体特征所显露出的生命密码，其内涵信息应该是多方面的，其中还应该包括体力、智力和情绪等多方面的潜在信息，而人们目前看到的人体潜在疾病信息，也只是其中的一部分。这些信息对于未来人类用最简单的办法，来发现人体潜在的优势或劣势，都有不可替代的预测价值。如将来人们要选拔未来的运动健将和未来的军事指挥人才，那么有关体相专家，只需仔细看看站在他面前的少年儿童的某些外部特征，就知道他们当中哪些人是哪方面的好苗子了。","path":"30_中级汉语分类阅读科技篇II/56_神秘_面相、手相、体相的科学.txt","line":"15","textbook":"30_中级汉语分类阅读科技篇II","lesson":"56_神秘_面相、手相、体相的科学"}],"evidenceUnit":"original_source_line"},{"id":"ANT:f6e2c052a867b593","words":["浪费","节约"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":3411,"first":"节约","second":"浪费"},{"line":14110,"first":"浪费","second":"节约"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"正常的导体都有电阻，通过电流时就会发热，这不仅浪费电能，而且过量的电流甚至会烧坏设备。所以大容量的输变电设施，往往还配有各种冷却设备。而如果应用超导技术，使用超导材料制成导线，因为没有电阻，就可以节约大量电能。所以用超导材料制成的装置，都会具有体积小、使用性能高、成本低的优点。","path":"16_基础科技汉语教程听力课本/30_超导材料.txt","line":"5","textbook":"16_基础科技汉语教程听力课本","lesson":"30_超导材料"}],"evidenceUnit":"original_source_line"},{"id":"ANT:27ee8ad726d7e519","words":["支出","收入"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":5607,"first":"收入","second":"支出"},{"line":7915,"first":"支出","second":"收入"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"负数还可以表示支出，正数表示收入。如支出sz元写作“sz元”，收入sz元写作“sz元”。所以，数学中正数和负数的作用是很大的。","path":"20_科技汉语读写教程/01_数学符号.txt","line":"7","textbook":"20_科技汉语读写教程","lesson":"01_数学符号"}],"evidenceUnit":"original_source_line"},{"id":"ANT:d6193e6cacf2e860","words":["亏损","盈利"],"status":"AI_SCREENED_CANDIDATE","researcherConfirmed":false,"dictionaryVerified":false,"sourceRows":[{"line":7253,"first":"盈利","second":"亏损"}],"synonymConflicts":[],"jointEvidence":[{"sentence":"比如，某保险公司出售的一种人身意外险单价为sz元，有sz万人购买该保险，则有sz万资金流入保险公司。如果有投保人发生意外，那么保险公司最多会赔付sz万元。此时我们可能有个疑问，如果有sz个人发生意外，那保险公司不就没有盈利了？如果发生意外的人数更多，保险公司岂不是会有很严重的亏损？其实我们不必担心，因为经过大量的统计分析，我们发现，个体意外身亡的概率仅有万分之一左右，假设sz万人中有sz人发生意外，保险公司要赔付sz万元，最后保险公司盈利sz万元。","path":"02_理工中文/05_第五章概率统计_04_教师应采用科学的评价指标来衡量学生的学习成果。.txt","line":"14","textbook":"02_理工中文","lesson":"05_第五章概率统计_04_教师应采用科学的评价指标来衡量学生的学习成果。"}],"evidenceUnit":"original_source_line"}]};
